INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parasite-eve-ii-usa-disc-2', 'Playstation', 'Parasite Eve II (USA) (Disc 2)', '1999', 'RPG', 'Square', '1', 'Survival action RPG', 'Survival horror with real-time RPG combat elements.', 'Uncover the conspiracy behind the creatures and save humanity.', 'The climactic conclusion to Aya Brea''s second adventure.', 'Parasite Eve II (Disc 2) ramps up the mystery and combat. Master the "Parasite Energy" powers to defeat massive biological threats in this Square classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('patriotic-pinball', 'Playstation', 'Patriotic Pinball', '1996', 'Pinball', 'American Softworks', '4', 'Arcade pinball', '2D pinball simulation with a patriotic American theme.', 'Score points on tables inspired by US history and landmarks.', 'A fast-paced and colorful pinball game for all ages.', 'Patriotic Pinball features tables like "America at War" and "The Road Trip." Master the flippers to unlock high scores in this star-spangled arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pepsiman-japan', 'Playstation', 'Pepsiman (Japan)', '1999', 'Action', 'KID', '1', 'Arcade action', 'High-speed 3D on-rails running game.', 'Deliver Pepsi to thirsty citizens while avoiding chaotic obstacles.', 'A cult-classic Japanese "runner" known for its absurdity.', 'Pepsiman is a frantic test of reflexes. Sprint through city streets and deserts to the beat of its iconic theme song in this hilarious arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('persona-2---eternal-punishment', 'Playstation', 'Persona 2 - Eternal Punishment', '2000', 'RPG', 'Atlus', '1', 'Japanese RPG', 'Traditional turn-based JRPG with a focus on psychological themes.', 'Solve the mystery of the Joker and the rumors coming true.', 'A dark and mature RPG that redefined the Shin Megami Tensei series.', 'Persona 2 - Eternal Punishment offers a deep "Rumor" system and complex characters. Face your inner demons in this stylish and cerebral JRPG masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('persona-2---innocent-sin-en-by-gemini-v10a', 'Playstation', 'Persona 2 - Innocent Sin [En by Gemini v1.0a]', '1999', 'RPG', 'Atlus', '1', 'Japanese RPG', 'Turn-based JRPG featuring the "Persona" summoning system.', 'Stop the masked man and solve the mystery of Sumaru City.', 'The English-translated prequel to Eternal Punishment.', 'Persona 2 - Innocent Sin [En by Gemini] finally makes this classic accessible. Experience the original story of Tatsuya in this fan-translated gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('persona-revelations', 'Playstation', 'Persona Revelations', '1996', 'RPG', 'Atlus', '1', 'Japanese RPG', 'First-person dungeon-crawling JRPG with turn-based battles.', 'Defend your city from a demonic invasion by summoning Personas.', 'The legendary first entry in the Persona franchise.', 'Persona Revelations (Shin Megami Tensei) blends urban fantasy with deep customization. Navigate complex dungeons and recruit demons to your cause.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-jacobsens-golden-tee-golf', 'Playstation', 'Peter Jacobsen''s Golden Tee Golf', '1996', 'Sports', 'Incredible Technologies', '4', 'Golf simulation', '3D golf simulation with an arcade-style feel.', 'Win professional tournaments by mastering wind and terrain.', 'A solid and accessible golf game for sports enthusiasts.', 'Peter Jacobsen''s Golden Tee Golf brings the classic arcade experience home. Master the swing mechanics and aim for a hole-in-one on diverse courses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pink-panther:-pinkadelic-pursuit', 'Playstation', 'Pink Panther: Pinkadelic Pursuit', '1998', 'Platformer', 'Wanderlust Interactive', '1', '3D platformer', '3D action-platformer featuring the iconic Pink Panther.', 'Navigate diverse levels to find the hidden treasure.', 'A colorful and family-friendly platformer with a groovy vibe.', 'Pink Panther: Pinkadelic Pursuit features gadgets and stealthy gameplay. Help the Pink Panther outsmart his enemies in this vibrant 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinobee', 'Playstation', 'Pinobee', '1999', 'Platformer', 'Hudson Soft', '1', '3D platformer', '2D side-scrolling platformer starring a robotic bee.', 'Explore a mechanical world to find your creator and friends.', 'A charming and visually unique platformer from Artoon.', 'Pinobee offers fluid aerial movement and multiple branching paths. Explore the vibrant environments of a tiny world in this cute handheld-style hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall-3d---beyond-the-jungle-usa', 'Playstation', 'Pitfall 3D - Beyond the Jungle (USA)', '1998', 'Platformer', 'Edge of Reality', '1', '3D platformer', '3D action-adventure with a jungle-survival theme.', 'Rescue your friends and defeat the evil Scourge.', 'A modern 3D evolution of the classic Pitfall series.', 'Pitfall 3D - Beyond the Jungle features the voice of Bruce Campbell. Navigate treacherous ruins and battle creatures in this cinematic platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plane-crazy-europe-proto', 'Playstation', 'Plane Crazy (Europe) (Proto)', '1996', 'Racing', 'Software Creations', '2', 'Arcade racing', 'High-speed 3D vehicular racing with combat elements.', 'Outrace rivals in futuristic planes across hazardous tracks.', 'A rare prototype of an unreleased high-speed flight racer.', 'Plane Crazy (Proto) offers a look at what could have been. Experience intense aerial racing and weaponized flight in this experimental title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-with-the-teletubbies-usa', 'Playstation', 'Play with the Teletubbies (USA)', '1999', 'Educational', 'BBC Multimedia', '1', 'Educational children game', 'Educational mini-games for young children.', 'Explore Teletubbyland and play games with Tinky Winky and Po.', 'A gentle and interactive game based on the popular TV show.', 'Play with the Teletubbies is designed for the youngest players. Safe, colorful, and repetitive gameplay perfect for early childhood development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poed', 'Playstation', 'PO''ed', '1995', 'Shooter', 'Any Channel', '2', 'First-person shooter', 'First-person shooter with a surreal and comedic theme.', 'Escape an alien-infested spaceship using bizarre weapons.', 'A quirky, early FPS known for its unique humor and "cook" protagonist.', 'PO''ed delivers fast-paced shooting and jetpack exploration. Fight weird enemies like walking butts and flying frying pans in this cult shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-fighter-usa', 'Playstation', 'Pocket Fighter (USA)', '2000', 'Fighting', 'Capcom', '2', '2D fighting', '2D crossover fighting game with "chibi" characters.', 'Defeat rivals to collect gems and power up your specials.', 'A hilarious and flashy fighter featuring Capcom legends.', 'Pocket Fighter (USA) offers simplified controls and amazing animations. Watch Ryu and Chun-Li transform into funny costumes in this chaotic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('point-blank-3', 'Playstation', 'Point Blank 3', '2000', 'Shooter', 'Namco', '2', 'Light gun shooter', 'Light-gun shooting gallery with mini-games and humor.', 'Complete various shooting challenges with speed and precision.', 'The definitive third entry in the frantic Point Blank series.', 'Point Blank 3 offers hundreds of quirky stages. Perfect for Guncon owners, it’s a high-energy multiplayer blast that tests your reflexes and aim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('policenauts-japan', 'Playstation', 'Policenauts (Japan)', '1996', 'Adventure', 'Konami', '1', 'Visual novel adventure', 'Cinematic point-and-click adventure with a sci-fi noir theme.', 'Investigate a conspiracy in a space colony as a former astronaut.', 'A narrative masterpiece from the creator of Metal Gear Solid.', 'Policenauts (Japan) is a beautifully animated interactive movie. Experience Hideo Kojima''s vision of a space-age mystery in this legendary title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pong---the-next-level-usa', 'Playstation', 'Pong - The Next Level (USA)', '1999', 'Action', 'Hasbro Interactive', '2', 'Arcade action', '3D update to the classic arcade paddle game.', 'Defeat opponents across various themed 3D environments.', 'A modern and creative reimagining of the original Pong.', 'Pong - The Next Level takes the paddle to new heights. Navigate obstacles and use power-ups in this stylish and addictive puzzle-action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pop-n-pop', 'Playstation', 'Pop n'' Pop', '1998', 'Puzzle', 'Success', '2', 'Arcade puzzle', 'Competitive bubble-matching puzzle game with a twist.', 'Clear the screen by matching colored balloons using various characters.', 'A vibrant and rhythmic puzzler from the makers of Bubble Bobble.', 'Pop n'' Pop offers a unique mechanic where you pull and throw balloons. Enjoy the catchy music and competitive play in this colorful Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-music---animation-melody-japan', 'Playstation', 'Pop''n Music - Animation Melody (Japan)', '1999', 'Rhythm', 'Konami', '2', 'Music rhythm game', 'Rhythm-based music game featuring anime themes.', 'Match the rhythm of famous anime songs using the Pop''n controller.', 'A special anime-focused edition of the popular rhythm series.', 'Pop''n Music - Animation Melody features tracks from classics like Dragon Ball and Sailor Moon. Perfect for rhythm fans and anime lovers alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-music---disney-tunes-japan', 'Playstation', 'Pop''n Music - Disney Tunes (Japan)', '1998', 'Rhythm', 'Konami', '2', 'Music rhythm game', 'Rhythm-based music game featuring Disney soundtracks.', 'Play along to the beat of iconic Disney movie songs.', 'A magical collaboration between Konami and Disney.', 'Pop''n Music - Disney Tunes brings the beat to the Magic Kingdom. Tap along to classic tunes in this family-friendly and rhythmic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-music-japan', 'Playstation', 'Pop''n Music (Japan)', '1998', 'Rhythm', 'Konami', '2', 'Music rhythm game', 'Foundational rhythm-based music game with colorful buttons.', 'Follow the beat of diverse J-pop and electronic tracks.', 'The game that started the massive Pop''n Music franchise.', 'Pop''n Music (Japan) is the peak of rhythmic fun. Use the specialized 9-button controller to master the charts in this vibrant arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-music-2-+-append-disc-japan', 'Playstation', 'Pop''n Music 2 + Append Disc (Japan)', '1999', 'Rhythm', 'Konami', '2', 'Music rhythm game', 'Rhythm-based music game with an expansion disc included.', 'Access new songs and refined gameplay in this updated collection.', 'A content-rich entry in the early Pop''n Music series.', 'Pop''n Music 2 + Append Disc offers more variety and better visuals. Experience the evolution of the rhythm genre with this Japanese hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-music-5-japan', 'Playstation', 'Pop''n Music 5 (Japan)', '2000', 'Rhythm', 'Konami', '2', 'Music rhythm game', '5th installment of the popular rhythm-action series.', 'Master new song lists and unlock secret characters.', 'A polished and energetic entry with a huge tracklist.', 'Pop''n Music 5 brings more style and faster beats. Challenge your reflexes with diverse music genres in this definitive Japanese rhythm game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popn-music-6-japan', 'Playstation', 'Pop''n Music 6 (Japan)', '2001', 'Rhythm', 'Konami', '2', 'Music rhythm game', '6th installment of the popular rhythm-action series.', 'Clear the most difficult charts and achieve high scores.', 'One of the most refined Pop''n entries for the original PS1.', 'Pop''n Music 6 features a massive library of catchy tunes. Enjoy the improved UI and vibrant animations in this high-energy music title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-play---sports-trivia', 'Playstation', 'Power Play - Sports Trivia', '1998', 'Trivia', '989 Studios', '4', 'Sports trivia', 'Interactive sports trivia game for multiple players.', 'Answer sports-related questions to prove your athletic knowledge.', 'A fun and competitive trivia game for sports fans.', 'Power Play - Sports Trivia is perfect for game nights. Test your memory on everything from baseball to boxing in this engaging quiz title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---lightspeed-rescue', 'Playstation', 'Power Rangers - Lightspeed Rescue', '2000', 'Action', 'Natsume', '2', 'Action adventure', '3D action-adventure based on the Lightspeed Rescue series.', 'Fight through titanium-armored enemies and save the city.', 'A high-energy brawler featuring vehicles and ranger combat.', 'Power Rangers - Lightspeed Rescue lets you pilot the Zords and fight as the rangers. Stop the demonic threat in this action-packed tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---time-force', 'Playstation', 'Power Rangers - Time Force', '2001', 'Action', 'Natsume', '2', 'Action adventure', '3D action-adventure featuring time-traveling heroes.', 'Stop Ransik and his army across various historical eras.', 'A diverse action game with melee combat and platforming.', 'Power Rangers - Time Force brings the TV show''s drama home. Travel through time and summon the Megazord to defeat giant monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-evolution-soccer-2', 'Playstation', 'Pro Evolution Soccer 2', '2001', 'Sports', 'Konami', '4', 'Soccer simulation', 'Realistic soccer simulation with tactical depth.', 'Win the international cup and lead your team to victory.', 'The beginning of the legendary Pro Evo (PES) series.', 'Pro Evolution Soccer 2 delivers refined ball physics and realistic AI. Experience the beautiful game with unmatched precision on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('professional-underground-league-of-pain', 'Playstation', 'Professional Underground League of Pain', '1997', 'Fighting', 'Eidos Interactive', '4', 'Arcade fighting', 'Hardcore wrestling/MMA hybrid fighting game.', 'Win brutal underground matches using realistic grappling and strikes.', 'A gritty and technical fighting game with a cult following.', 'Professional Underground League of Pain offers a realistic take on combat sports. Master the ground game to dominate your rivals in this tough fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('project-overkill-usa', 'Playstation', 'Project Overkill (USA)', '1996', 'Shooter', 'Crystal Dynamics', '2', 'Isometric shooter', 'Isometric squad-based shooter with heavy violence.', 'Infiltrate enemy bases and eliminate everyone in your path.', 'A chaotic and gore-filled action game with a dark sci-fi tone.', 'Project Overkill features 50 levels of intense isometric carnage. Choose your mercenary and blast through waves of mutants and soldiers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psychic-detective-usa-disc-1', 'Playstation', 'Psychic Detective (USA) (Disc 1)', '1995', 'Adventure', 'Electronic Arts', '1', 'Interactive movie', 'FMV-based psychological thriller and adventure.', 'Navigate the mind of a murder victim to solve the crime.', 'A cinematic mystery spanning three massive discs.', 'Psychic Detective (Disc 1) begins an experimental journey. Use psychic powers to hop into different perspectives in this unique interactive movie.');
