INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psychic-detective-usa-disc-3', 'Playstation', 'Psychic Detective (USA) (Disc 3)', '1995', 'Adventure', 'Electronic Arts', '1', 'Interactive movie', 'FMV-based psychological thriller and adventure.', 'Reach the final confrontation and unmask the killer.', 'The dramatic and multiple-ending conclusion to the psychic saga.', 'Psychic Detective (Disc 3) offers a variety of outcomes based on your choices. Witness the final twists in this groundbreaking interactive mystery.');
