INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psychic-force-2', 'Playstation', 'Psychic Force 2', '1999', 'Fighting', 'Taito', '2', '3D fighting', '3D weaponless fighting game in a cubic arena.', 'Defeat psychic rivals in 360-degree aerial combat.', 'An intense sequel to the psychic-powered fighting hit.', 'Psychic Force 2 features expanded mechanics and new characters. Master the "Psychic Gauge" to unleash devastating energy attacks in a full 3D void.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('punky-skunk', 'Playstation', 'Punky Skunk', '1996', 'Platformer', 'Manley & Associates', '1', '3D platformer', '2D side-scrolling platformer with a mascot theme.', 'Use your extreme gear to stop the Badler Empire.', 'A quirky and colorful platformer starring a radical skunk.', 'Punky Skunk offers high-energy platforming with snowboards, pogo sticks, and more. Explore vibrant worlds and defeat bosses in this 32-bit hidden gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putter-golf', 'Playstation', 'Putter Golf', '1999', 'Sports', 'HammerHead', '4', 'Arcade mini golf', '3D miniature golf simulation.', 'Complete the courses in the fewest strokes possible.', 'A simple and accessible arcade-style golf game.', 'Putter Golf provides various themed courses and obstacles. Master the angles and power of your shots to conquer every hole in this sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-4---car-kun-to-issho', 'Playstation', 'Puyo Puyo 4 - Car-Kun to Issho', '1997', 'Puzzle', 'Compile', '2', 'Tile-matching puzzle', 'Competitive color-matching puzzle game.', 'Defeat opponents by creating chain reactions of slimes.', 'A charming Puyo Puyo entry featuring the mascot Car-kun.', 'Puyo Puyo 4 (Car-Kun to Issho) combines classic puzzle gameplay with cute animations. Perfect for fans of the series seeking competitive and fun matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-box', 'Playstation', 'Puyo Puyo Box', '2000', 'Puzzle', 'Compile', '2', 'Compilation puzzle', 'Compilation of classic Puyo Puyo titles and RPG modes.', 'Relive the history of Puyo Puyo with various game modes.', 'The ultimate collection for fans of the Puyo series.', 'Puyo Puyo Box includes ports of the original games plus a unique "Quest" mode. Customize your experience in this definitive puzzle package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-sun---ketteiban', 'Playstation', 'Puyo Puyo Sun - Ketteiban', '1997', 'Puzzle', 'Compile', '2', 'Tile-matching puzzle', 'Competitive color-matching puzzle with "Sun" mechanics.', 'Outscore rivals and clear the board to defeat the Sun.', 'The third installment featuring solar-powered power-ups.', 'Puyo Puyo Sun - Ketteiban introduces "Sun Puyos" to spice up combos. Enjoy the vibrant 32-bit graphics and fast-paced competitive puzzle action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-tsuu---ketteiban', 'Playstation', 'Puyo Puyo Tsuu - Ketteiban', '1997', 'Puzzle', 'Compile', '2', 'Tile-matching puzzle', 'Refined competitive color-matching puzzle.', 'Defeat a tower of opponents to become the Puyo champion.', 'A polished version of the legendary Puyo Puyo 2.', 'Puyo Puyo Tsuu - Ketteiban is the gold standard for competitive play. Master the "Oujyo" (counter) mechanic in this addictive puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-star-sweep', 'Playstation', 'Puzzle Star Sweep', '1997', 'Puzzle', 'Square', '1', 'Action puzzle', 'Fast-paced 2D tile-matching puzzle game.', 'Match and clear falling stars before the board fills up.', 'A rhythmic and colorful action-puzzle experience.', 'Puzzle Star Sweep tests your speed and reflexes. Plan your moves to create massive chains and outscore your opponents in this frantic puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzznic', 'Playstation', 'Puzznic', '1990', 'Puzzle', 'Taito', '2', 'Arcade puzzle', '2D puzzle game involving sliding tiles and logic.', 'Match all identical tiles to clear them from the level.', 'A digital port of the classic arcade logic game.', 'Puzznic challenges your spatial reasoning across hundreds of levels. Slide blocks carefully to solve increasingly difficult puzzles in this retro hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('q-bert', 'Playstation', 'Q-bert', '1999', 'Action', 'Titmouse', '2', 'Arcade action', '3D isometric puzzle game based on the arcade classic.', 'Change the color of every cube on the pyramid by jumping.', 'A modern and colorful update to the legendary 1982 game.', 'Q-bert on PS1 features classic gameplay with updated graphics and new challenges. Dodge enemies like Coily and Slick in this addictive arcade revival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('qix-neo', 'Playstation', 'Qix Neo', '1999', 'Puzzle', 'Taito', '2', 'Arcade puzzle', '2D area-capture puzzle game with updated visuals.', 'Claim over 75% of the screen while avoiding the Stix.', 'A flashy reimagining of the classic arcade hit Qix.', 'Qix Neo brings the tense, line-drawing gameplay to the 32-bit era. Experience the risk-vs-reward thrill with a modern techno aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quake-ii-usa', 'Playstation', 'Quake II (USA)', '1997', 'Shooter', 'id Software', '4', 'First-person shooter', 'First-person sci-fi shooter with heavy weaponry.', 'Infiltrate the Strogg home planet and stop the alien invasion.', 'A landmark FPS known for its intense action and dark tone.', 'Quake II delivers visceral combat and atmospheric levels. Blast through cybernetic horrors with the BFG and Railgun in this iconic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('r-type-delta-usa', 'Playstation', 'R-Type Delta (USA)', '1998', 'Shooter', 'Irem', '1', 'Side-scrolling shooter', 'Side-scrolling 2.5D "shmup" with biological themes.', 'Defeat the Bydo Empire using a variety of specialized ships.', 'The cinematic and highly-acclaimed evolution of R-Type.', 'R-Type Delta features the "Dose System" and incredible 3D boss fights. Master the iconic Force pods in this definitive PlayStation shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('racing-lagoon', 'Playstation', 'Racing Lagoon', '1999', 'RPG', 'Square', '1', 'Racing RPG', 'Open-world racing RPG with car customization.', 'Win illegal street races to upgrade your car''s parts.', 'A unique "High Speed RPG" from the creators of Final Fantasy.', 'Racing Lagoon blends narrative depth with intense street racing. Customize your ride''s engine and chassis in a neon-lit 90s Yokohama.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rakugaki-showtime', 'Playstation', 'Rakugaki Showtime', '1999', 'Action', 'Treasure', '4', 'Arcade brawler', 'Arena-based 2D brawler with a sketch-style art.', 'Be the last fighter standing in chaotic, creative battles.', 'A rare and stylish cult classic from the makers of Treasure.', 'Rakugaki Showtime features fast-paced, physics-based combat. Throw objects and use special moves in this visually unique brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage---through-time-usa', 'Playstation', 'Rampage - Through Time (USA)', '1999', 'Action', 'Midway', '4', 'Arcade destruction', '3D monster-smashing action across different eras.', 'Destroy historical landmarks as giant mutated monsters.', 'A chaotic and humorous entry in the Rampage series.', 'Rampage - Through Time lets you smash through the past and future. Play as George, Lizzie, or Ralph in this explosive arcade-style hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage---world-tour', 'Playstation', 'Rampage - World Tour', '1997', 'Action', 'Midway', '4', 'Arcade destruction', '2D monster-smashing action on a global scale.', 'Destroy cities around the world to stop the Scumlabs labs.', 'A faithful port of the popular arcade monster brawler.', 'Rampage - World Tour offers non-stop destruction and humor. Eat citizens and topple skyscrapers in this classic arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage-2---universal-tour', 'Playstation', 'Rampage 2 - Universal Tour', '1999', 'Action', 'Midway', '4', 'Arcade destruction', '3D monster-smashing action with an intergalactic theme.', 'Rescue your monster friends and defeat the alien invaders.', 'The expanded sequel with new characters and larger levels.', 'Rampage 2 - Universal Tour takes the carnage to outer space. Enjoy the same addictive destruction with even more monstrous variety.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rascal-usa', 'Playstation', 'Rascal (USA)', '1998', 'Platformer', 'Traveller''s Tales', '1', '3D platformer', '3D action-platformer featuring a boy with a bubble gun.', 'Navigate a haunted house to rescue your friend and escape.', 'A visually impressive early 3D platformer from Traveller''s Tales.', 'Rascal features innovative lighting and large levels. Explore different time periods and fight clockwork enemies in this challenging quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman', 'Playstation', 'Rayman', '1995', 'Platformer', 'Ubisoft', '1', '2D platformer', '2D side-scrolling platformer with vibrant hand-drawn art.', 'Rescue the Electoons and defeat the evil Mr. Dark.', 'A beautiful and notoriously difficult platforming masterpiece.', 'Rayman features a unique art style and challenging mechanics. Use your hair-copter and telescopic fist to navigate a whimsical world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-2---the-great-escape', 'Playstation', 'Rayman 2 - The Great Escape', '1999', 'Platformer', 'Ubisoft', '1', '3D platformer', '3D platformer featuring a wide world and epic story.', 'Defeat Admiral Razorbeard and his army of Robo-Pirates.', 'Widely considered one of the best 3D platformers ever made.', 'Rayman 2 - The Great Escape is a cinematic and atmospheric journey. Experience fluid gameplay and a magical story in this landmark title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-rush', 'Playstation', 'Rayman Rush', '2000', 'Racing', 'Ubisoft', '2', 'Arcade racing', '3D kart-style racing with foot-racing mechanics.', 'Beat your rivals in high-speed races across Rayman worlds.', 'A fast-paced and competitive foot-racer for the PS1.', 'Rayman Rush features multiple characters and power-ups. Master the shortcuts and use your abilities to cross the finish line first.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('re-loaded---the-hardcore-sequel-usa', 'Playstation', 'Re-Loaded - The Hardcore Sequel (USA)', '1996', 'Shooter', 'Psygnosis', '2', 'Twin-stick shooter', 'Top-down run-and-gun shooter with extreme violence.', 'Blast your way through a space-prison to take revenge.', 'The darker and grittier sequel to the cult classic "Loaded."', 'Re-Loaded features chaotic shooting and gore-filled levels. Choose from a cast of deranged anti-heroes in this intense brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-bout-garou-densetsu-japan-enja', 'Playstation', 'Real Bout Garou Densetsu (Japan) (En,Ja)', '1995', 'Fighting', 'SNK', '2', '2D fighting', '2D team-based fighting game from the Fatal Fury series.', 'Defeat Geese Howard in the ultimate South Town tournament.', 'A technical and flashy fighter with "Ring Out" mechanics.', 'Real Bout Garou Densetsu brings the SNK arcade experience to PS1. Master the line-swaying system and unleash massive special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('real-bout-garou-densetsu-special---dominated-mind-japan', 'Playstation', 'Real Bout Garou Densetsu Special - Dominated Mind (Japan)', '1999', 'Fighting', 'SNK', '2', '2D fighting', '2D fighting game with a focus on story and unique mechanics.', 'Stop the brainwashing plot and defeat the shadow organization.', 'A specialized version of Real Bout Special with exclusive content.', 'Real Bout Special - Dominated Mind features White as the final boss and exclusive anime cutscenes. A must-play for Fatal Fury fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('reboot-usa', 'Playstation', 'ReBoot (USA)', '1998', 'Adventure', 'ReBoot Productions', '1', 'Action adventure', '3D action-adventure based on the CGI animated series.', 'Help Bob and Dot defend Mainframe from Megabyte and Hexadecimal.', 'A faithful adaptation of the groundbreaking TV show.', 'ReBoot brings the digital world to life. Complete missions, fly vehicles, and "Mend" the tears in this high-tech adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rescue-copter', 'Playstation', 'Rescue Copter', '1997', 'Simulation', 'Psygnosis', '1', 'Helicopter rescue', '3D helicopter-based rescue and combat simulator.', 'Complete dangerous rescue missions and neutralize enemy threats.', 'A tactical and challenging flight-action game.', 'Rescue Copter tests your piloting skills. Balance speed and safety to save civilians in various high-stakes scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil', 'Playstation', 'Resident Evil', '1996', 'Horror', 'Capcom', '1', 'Survival horror', 'Survival horror with a focus on exploration and resource management.', 'Investigate the Spencer Mansion and survive the T-Virus outbreak.', 'The legendary game that defined the survival horror genre.', 'Resident Evil (Biohazard) delivers terrifying atmosphere and puzzles. Choose between Chris or Jill to uncover the secrets of Umbrella.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil---directors-cut---dual-shock-ver', 'Playstation', 'Resident Evil - Director''s Cut - Dual Shock Ver.', '1997', 'Horror', 'Capcom', '1', 'Survival horror', 'Enhanced survival horror with new modes and difficulty.', 'Survive the mansion with rearranged items and new camera angles.', 'The definitive version of the original game for PS1.', 'Resident Evil - Director''s Cut adds "Arranged Mode" and Dual Shock support. Experience the horror again with fresh challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-2---dual-shock-ver-disc-1-leon', 'Playstation', 'Resident Evil 2 - Dual Shock Ver. (Disc 1) (Leon)', '1998', 'Horror', 'Capcom', '1', 'Survival horror', 'Survival horror set in a city-wide zombie outbreak.', 'Escape Raccoon City as rookie cop Leon S. Kennedy.', 'A massive sequel with the "Zapping System" and cinematic action.', 'Resident Evil 2 (Leon) features a deep story and terrifying bosses. Master the B-Scenario to see the true ending of the disaster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-2---dual-shock-ver-disc-2-claire', 'Playstation', 'Resident Evil 2 - Dual Shock Ver. (Disc 2) (Claire)', '1998', 'Horror', 'Capcom', '1', 'Survival horror', 'Survival horror set in a city-wide zombie outbreak.', 'Help Claire Redfield find her brother amidst the Raccoon City chaos.', 'The parallel journey that reveals the other side of the outbreak.', 'Resident Evil 2 (Claire) offers unique weapons and story paths. Survive the RCPD and the sewers in this landmark horror hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-3-nemesis-brazilian-portuguese', 'Playstation', 'Resident Evil 3 Nemesis (Brazilian Portuguese)', '1999', 'Horror', 'Capcom', '1', 'Survival horror', 'Survival horror featuring an unstoppable hunter.', 'Help Jill Valentine escape Raccoon City before it''s destroyed.', 'A tense and action-packed entry with the "Live Selection" system.', 'Resident Evil 3 Nemesis (Portuguese) brings the horror to Brazil. Experience the chase of the Nemesis in your native language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-3:-nemesis-russian', 'Playstation', 'Resident Evil 3: Nemesis (Russian)', '1999', 'Horror', 'Capcom', '1', 'Survival horror', 'Survival horror featuring an unstoppable hunter.', 'Escape the city and avoid the relentless Nemesis creature.', 'The Russian localized version of Jill''s final escape.', 'Resident Evil 3: Nemesis (Russian) allows fans to experience the cinematic terror and intense puzzles with localized text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-3:-nemesis-u', 'Playstation', 'Resident Evil 3: Nemesis (U)', '1999', 'Horror', 'Capcom', '1', 'Survival horror', 'Survival horror featuring an unstoppable hunter.', 'Master the "Dodge" mechanic and survive the Nemesis encounters.', 'The original North American release of the horror classic.', 'Resident Evil 3: Nemesis features a more action-oriented pace. Every choice you make impacts your survival in the crumbling city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-survivor', 'Playstation', 'Resident Evil Survivor', '2000', 'Shooter', 'Capcom', '1', 'First-person survival horror', 'First-person light-gun shooter with survival horror themes.', 'Survive a remote island outbreak and regain your lost memories.', 'A unique spin-off blending FPS action with RE atmosphere.', 'Resident Evil Survivor offers a different perspective on the franchise. Fight zombies and Tyrants in this fast-paced first-person adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revolution-x---music-is-the-weapon-usa', 'Playstation', 'Revolution X - Music Is the Weapon (USA)', '1995', 'Shooter', 'Midway', '2', 'Arcade rail shooter', 'On-rails arcade shooter featuring the band Aerosmith.', 'Rescue Aerosmith and defeat the New Order Nation.', 'A loud, fast-paced arcade shooter with a rock ''n'' roll vibe.', 'Revolution X puts you in a dystopian future where music is banned. Use explosive CDs to blast enemies and save the band in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ridge-racer', 'Playstation', 'Ridge Racer', '1994', 'Racing', 'Namco', '2', 'Arcade racing', 'High-speed arcade racing with drifting mechanics.', 'Win the GP and unlock the "Devil" car in the final race.', 'The iconic launch title that defined PlayStation''s power.', 'Ridge Racer delivers pure 32-bit arcade adrenaline. Master the power-slide and enjoy the legendary techno soundtrack in this racing milestone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ridge-racer-japan', 'Playstation', 'Ridge Racer (Japan)', '1994', 'Racing', 'Namco', '2', 'Arcade racing', 'High-speed arcade racing with drifting mechanics.', 'Defeat the competition on the seaside tracks of Japan.', 'The original Japanese release of the legendary arcade port.', 'Ridge Racer (Japan) offers the authentic 1994 experience. Witness the beginning of the drifting phenomenon with pixel-perfect arcade handling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ridge-racer-revolution', 'Playstation', 'Ridge Racer Revolution', '1995', 'Racing', 'Namco', '2', 'Arcade racing', 'Arcade racing sequel with refined drifting and new tracks.', 'Conquer the three new circuits and defeat the boss cars.', 'An explosive sequel with improved graphics and faster gameplay.', 'Ridge Racer Revolution ramps up the challenge. Featuring a high-energy soundtrack and secret cars, it''s a must-play for arcade racing fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ridge-racer-turbo', 'Playstation', 'Ridge Racer Turbo', '1995', 'Racing', 'Namco', '2', 'Arcade racing', 'High-speed racing tech demo running at 60fps.', 'Complete the course as fast as possible in a smooth 60fps.', 'A special bonus disc known for its incredible frame rate.', 'Ridge Racer Turbo (R4 Bonus) shows the true power of the PS1. Experience the smoothest racing on the console in this technical marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ridge-racer-type-4', 'Playstation', 'Ridge Racer Type 4', '1998', 'Racing', 'Namco', '2', 'Arcade racing', 'Cinematic racing with multiple storylines and teams.', 'Win the Real Racing Roots ''99 tournament for your team.', 'Widely considered the best racing game on the PlayStation.', 'Ridge Racer Type 4 (R4) features stunning visuals and a deep career mode. Unlock 320 unique cars in this masterpiece of style and speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-2---resurrection-usa-enfrdeesit', 'Playstation', 'Rise 2 - Resurrection (USA) (En,Fr,De,Es,It)', '1996', 'Shooter', 'Apogee Software', '2', 'First-person shooter', '2D fighting game with pre-rendered robotic characters.', 'Win the robot tournament and survive the mechanical war.', 'A gritty and metallic sequel to the "Rise of the Robots."', 'Rise 2 - Resurrection features improved combat and diverse cyborgs. Experience the "Fatalities" of the robot world in this dark sci-fi brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rising-zan---the-samurai-gunman', 'Playstation', 'Rising Zan - The Samurai Gunman', '1999', 'Action', 'UFO Interactive', '1', 'Action adventure', 'Third-person action-adventure with a mix of swords and guns.', 'Defeat the western-themed demons in "The Land of the Rising Zan."', 'A wild and hilarious mix of Samurai action and Cowboy style.', 'Rising Zan: The Samurai Gunman is a cult classic known for its humor. Cut through enemies or blast them away in this stylish 3D action gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rittai-ninja-katsugeki---tenchu-japan', 'Playstation', 'Rittai Ninja Katsugeki - Tenchu (Japan)', '1998', 'Action', 'Acquire', '1', 'Stealth action', '3D stealth-action game featuring two ninja protagonists.', 'Infiltrate enemy castles and assassinate corrupt lords.', 'The original Japanese release of the legendary "Tenchu."', 'Rittai Ninja Katsugeki - Tenchu redefined stealth. Master the grappling hook and silent kills in this authentic feudal Japanese adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rival-schools:-united-by-fate', 'Playstation', 'Rival Schools: United by Fate', '1998', 'Fighting', 'Capcom', '2', '3D fighting', '2D tag-team fighting game with high-school students.', 'Defeat the dark forces kidnapping students and teachers.', 'A flashy and creative Capcom fighter with cinematic specials.', 'Rival Schools: United by Fate features two discs: Arcade and Evolution. Enjoy deep team mechanics and a vibrant cast of school-aged brawlers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash', 'Playstation', 'Road Rash', '1994', 'Racing', 'Electronic Arts', '2', 'Arcade motorcycle racing', 'Combat-based motorcycle racing with melee weapons.', 'Win the race while knocking rivals off their bikes with clubs.', 'A gritty and addictive arcade racer with a rebel attitude.', 'Road Rash brings vehicular combat to the streets. Dodge traffic and outrun the police while battling other bikers in this high-speed hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-3d', 'Playstation', 'Road Rash 3D', '1996', 'Racing', 'Electronic Arts', '2', 'Arcade motorcycle racing', '3D motorcycle racing with heavy combat elements.', 'Survive the high-speed chases and beat down your rivals.', 'The first 3D entry in the legendary combat-racing series.', 'Road Rash 3D offers a new perspective on bike brawling. Navigate traffic and use chains to dominate the highway in this intense 32-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-jailbreak', 'Playstation', 'Road Rash Jailbreak', '2000', 'Racing', 'Electronic Arts', '2', 'Arcade motorcycle racing', 'Mission-based motorcycle combat and racing.', 'Complete various gang-related missions and win races.', 'An action-heavy evolution of the Road Rash formula.', 'Road Rash Jailbreak features a deep career mode and sidecar combat. Experience the chaos of the road with more weapons and technical moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roadsters', 'Playstation', 'Roadsters', '1999', 'Racing', 'Magnetic Fields', '2', 'Arcade racing', 'Arcade-style racing with customizable roadsters.', 'Win championships across diverse international circuits.', 'A fast and accessible racer with a focus on open-top cars.', 'Roadsters offers a variety of modes and weather effects. Master the handling of high-performance cars in this colorful 3D racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robo-pit', 'Playstation', 'Robo Pit', '1997', 'Fighting', 'Almanic', '2', '3D fighting', '3D arena-based robot combat with customization.', 'Build the ultimate robot and win the arena tournament.', 'A technical and creative brawler featuring modular robots.', 'Robo Pit lets you customize your fighter''s arms and legs for different tactics. Fight through the ranks to become the champion of the pit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robo-pit-2', 'Playstation', 'Robo Pit 2', '2001', 'Fighting', 'Almanic', '2', '3D fighting', '3D arena-based robot combat with expanded parts.', 'Create a mechanical fighter and dominate the global arena.', 'An improved sequel with more parts and faster combat.', 'Robo Pit 2 offers deeper customization and better visuals. Build a specialized robot to counter every opponent in this intense sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocod---james-pond-ii-europe-enfrdeesit', 'Playstation', 'Robocod - James Pond II (Europe) (En,Fr,De,Es,It)', '1991', 'Platformer', 'Millennium Interactive', '1', '2D platformer', '2D side-scrolling platformer starring a secret agent fish.', 'Rescue the toys and defeat the evil Dr. Maybe in his factory.', 'A charming and colorful classic from the 16-bit era.', 'Robocod - James Pond II features a unique stretching mechanic. Explore diverse levels and find hidden secrets in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robotron', 'Playstation', 'Robotron', '1998', 'Shooter', 'Taito', '2', 'Arcade shooter', 'Fast-paced 2D isometric shooter with twin-stick controls.', 'Rescue the humans and destroy the endless robot waves.', 'A modern and explosive remake of the arcade classic.', 'Robotron X delivers non-stop shooting action. Experience the frantic gameplay of the original with 3D visuals and a techno soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-complete-works', 'Playstation', 'Rockman Complete Works', '1999', 'Compilation', 'Capcom', '1', 'Classic game collection', 'Compilation of classic Mega Man titles with new features.', 'Relive the 8-bit classics with updated UI and soundtracks.', 'The definitive Japanese collection of the NES Mega Man games.', 'Rockman Complete Works features ports of the first six games. Enjoy the "Navi Mode" and extra challenges in these pixel-perfect versions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rollcage-usa', 'Playstation', 'Rollcage (USA)', '1999', 'Racing', 'Attention to Detail', '2', 'Arcade combat racing', 'High-speed futuristic racing with 360-degree tracks.', 'Win races and use weapons to destroy your competition.', 'A fast and aggressive racer similar to WipEout but on wheels.', 'Rollcage features gravity-defying tracks and explosive combat. Drive on walls and ceilings in this high-octane 32-bit racing hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rollcage-stage-ii-usa', 'Playstation', 'Rollcage Stage II (USA)', '2000', 'Racing', 'Attention to Detail', '2', 'Arcade combat racing', 'Futuristic combat racing with improved physics and speed.', 'Dominate the league and master the "Scramble" mode.', 'A polished and incredibly fast sequel to the original Rollcage.', 'Rollcage Stage II offers better car handling and more weapons. Experience the ultimate in high-speed, 360-degree combat racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---search-for-reptar', 'Playstation', 'Rugrats - Search for Reptar', '1998', 'Adventure', 'Behaviour Interactive', '1', 'Children''s adventure', '3D adventure featuring the iconic Nickelodeon babies.', 'Find Reptar''s missing puzzle pieces in the Pickles'' house.', 'A nostalgic and faithful adaptation of the hit cartoon show.', 'Rugrats - Search for Reptar features mini-games like "Mini-Golf" and "Hide and Seek." Perfect for fans of the show and younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---studio-tour-usa', 'Playstation', 'Rugrats - Studio Tour (USA)', '1999', 'Adventure', 'Behaviour Interactive', '1', 'Children''s adventure', 'Mini-game collection set in a Hollywood movie studio.', 'Complete diverse tasks and games to find the golden tickets.', 'A colorful and fun variety game starring the Rugrats cast.', 'Rugrats - Studio Tour takes the babies to the movies. Experience diverse themes from sci-fi to westerns in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saga-frontier-usa', 'Playstation', 'SaGa Frontier (USA)', '1998', 'RPG', 'Square', '1', 'Japanese RPG', 'Non-linear JRPG with seven different protagonists.', 'Follow your chosen hero''s unique story to save the world.', 'A deep and complex RPG known for its "Free Scenario" system.', 'SaGa Frontier offers immense replayability with its branching paths. Master the unique "Glimmer" combat system in this Square classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saga-frontier-2-usa', 'Playstation', 'SaGa Frontier 2 (USA)', '1999', 'RPG', 'Square', '1', 'Japanese RPG', 'Narrative-driven JRPG with a watercolor art style.', 'Uncover the mystery of the "Egg" across multiple generations.', 'A beautiful and artistic departure for the SaGa series.', 'SaGa Frontier 2 features stunning hand-drawn visuals and a deep story. Experience tactical grid-based battles in this landmark 32-bit RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sammy-sosa-high-heat-baseball-2001', 'Playstation', 'Sammy Sosa High Heat Baseball 2001', '2000', 'Sports', '3DO', '4', 'Baseball simulation', 'Realistic 3D baseball simulation with 2001 rosters.', 'Lead your team to the World Series in this deep simulation.', 'A technical and feature-rich baseball game for the PS1.', 'Sammy Sosa High Heat Baseball 2001 offers authentic stats and play. Master the pitching and batting to dominate the major leagues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sammy-sosa-softball-slam', 'Playstation', 'Sammy Sosa Softball Slam', '2000', 'Sports', 'Crystal Dynamics', '4', 'Arcade softball', 'Arcade-style softball game featuring the legendary Sammy Sosa.', 'Win the tournament with explosive dunks... wait, home runs!', 'A fast-paced and fun take on the sport of softball.', 'Sammy Sosa Softball Slam features colorful graphics and accessible controls. Enjoy a quick game of ball with over-the-top animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-shodown---warriors-rage-usa', 'Playstation', 'Samurai Shodown - Warriors Rage (USA)', '1999', 'Fighting', 'SNK', '2', '3D weapon-based fighting', '3D weapon-based fighting game set in the future.', 'Defeat the dark organization and win the ultimate duel.', 'A 3D spin-off of the legendary Samurai Shodown series.', 'Samurai Shodown - Warriors Rage features iconic characters like Haohmaru. Master the technical sword-play in this unique 3D arena brawler.');
