INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('san-francisco-rush---extreme-racing', 'Playstation', 'San Francisco Rush - Extreme Racing', '1997', 'Racing', 'Atari Games', '4', 'Arcade racing', 'Port of the high-speed arcade racing hit.', 'Finish first across a variety of extreme 3D tracks.', 'A fast and chaotic racer known for its massive jumps.', 'San Francisco Rush brings the arcade thrill to PS1. Master the shortcuts and survive the crashes in this explosive racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scooby-doo-and-the-cyber-chase', 'Playstation', 'Scooby-Doo and the Cyber Chase', '2001', 'Adventure', 'Helixe', '1', 'Action adventure', 'Action-adventure based on the Scooby-Doo movie.', 'Stop the Phantom Virus and escape the digital world.', 'A fun and atmospheric quest featuring the mystery gang.', 'Scooby-Doo and the Cyber Chase features puzzles, platforming, and snacks. Help the gang solve the mystery in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scooby-doo!-night-of-100-frights-usa-proto', 'Playstation', 'Scooby-Doo! Night of 100 Frights (USA) (Proto)', '2002', 'Adventure', 'Helixe', '1', 'Action adventure', 'Third-person action-adventure prototype.', 'Explore a haunted mansion and unmask the spooky villain.', 'A rare look at a 3D Scooby adventure that never fully released.', 'Scooby-Doo! Night of 100 Frights (Proto) offers early platforming mechanics and exploration. Solve the mystery in this unreleased 32-bit gem.');
