INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam---ggeneration', 'Playstation', 'SD Gundam - GGeneration', '1998', 'Strategy', 'Bandai', '1', 'Tactical strategy RPG', 'Tactical strategy game featuring the SD Gundam universe.', 'Lead your fleet to victory in various Gundam storylines.', 'A deep and strategic RPG for Gundam and mecha fans.', 'SD Gundam - GGeneration features massive rosters of Mobile Suits. Customize your units and dominate the battlefield in this tactical hit.');
