INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sesame-street-sports', 'Playstation', 'Sesame Street Sports', '1998', 'Sports', 'Recreational Software Designs', '4', 'Children''s sports', 'Collection of sports mini-games for young children.', 'Compete in races and games with Elmo and his friends.', 'A safe and educational sports game for preschoolers.', 'Sesame Street Sports features accessible controls and positive messages. Join the Muppets in fun athletic activities designed for early childhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sexy-parodius', 'Playstation', 'Sexy Parodius', '1996', 'Shooter', 'Konami', '2', 'Arcade shooter', 'Side-scrolling 2D "shmup" with humorous and mature themes.', 'Blast through surreal levels to complete various missions.', 'A wacky and polished parody of the Gradius series.', 'Sexy Parodius offers tight shooting mechanics and absurd humor. Choose from a roster of bizarre characters in this visually vibrant Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sexy-parodius-japan', 'Playstation', 'Sexy Parodius (Japan)', '1996', 'Shooter', 'Konami', '2', 'Arcade shooter', 'Side-scrolling 2D "shmup" with humorous and mature themes.', 'Blast through surreal levels to complete various missions.', 'The original Japanese release of the cult-favorite shooter.', 'Sexy Parodius (Japan) features the iconic "Option" system and branching paths. Experience the pinnacle of Konami''s parodical shooter series.');
