INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaman-king---spirit-of-shamans', 'Playstation', 'Shaman King - Spirit of Shamans', '2001', 'Fighting', 'DreamFactory', '2', '3D fighting', '2D fighting game based on the popular manga and anime.', 'Win the Shaman Fight to become the ultimate Shaman King.', 'A stylish and technical brawler featuring spirit summons.', 'Shaman King - Spirit of Shamans features beautiful sprite art. Master your "Oversoul" and execute devastating special moves to win the tournament.');
