INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shrek-treasure-hunt', 'Playstation', 'Shrek Treasure Hunt', '2002', 'Adventure', 'Blue Tongue Entertainment', '1', 'Puzzle adventure', '3D platformer and mini-game collection for kids.', 'Help Shrek find the hidden treasures to win the competition.', 'A family-friendly adventure based on the DreamWorks film.', 'Shrek Treasure Hunt features exploration and puzzles. Help your favorite ogre navigate the swamp in this lighthearted and colorful quest.');
