INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-usa', 'Playstation', 'South Park (USA)', '1998', 'Adventure', 'Iguana Entertainment', '1', 'Action adventure', 'First-person shooter with the cast of South Park.', 'Defeat turkeys, clones, and aliens to save the town.', 'A chaotic and funny shooter with a focus on slapstick humor.', 'South Park brings the TV show''s irreverent style to the PS1. Use unconventional weapons like snowball launchers to protect the quiet mountain town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-rally-usa', 'Playstation', 'South Park Rally (USA)', '2000', 'Racing', 'Tantalus Interactive', '4', 'Arcade racing', '3D kart racing with a focus on vehicular combat.', 'Win races across South Park by any means necessary.', 'A wacky and offensive racer with power-ups and gadgets.', 'South Park Rally features dozens of playable characters and secret unlocks. Race through the most iconic locations from the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-europe', 'Playstation', 'Space Invaders (Europe)', '1999', 'Shooter', 'Taito', '2', 'Classic arcade shooter', '2D fixed-shooter based on the arcade legendary hit.', 'Defend Earth from descending waves of alien invaders.', 'The European version of the foundational arcade classic.', 'Space Invaders brings the 1978 phenomenon home with updated visuals. Master the shields and outlast the alien swarm in this retro hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-japan', 'Playstation', 'Space Invaders (Japan)', '1999', 'Shooter', 'Taito', '2', 'Classic arcade shooter', '2D fixed-shooter based on the arcade legendary hit.', 'Defend Earth from descending waves of alien invaders.', 'The original Japanese release of the iconic Taito shooter.', 'Space Invaders (Japan) offers the pure, unadulterated arcade experience. Relive the history of video games with pixel-perfect gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-usa', 'Playstation', 'Space Invaders (USA)', '1999', 'Shooter', 'Taito', '2', 'Classic arcade shooter', '3D reimagining of the classic fixed-shooter.', 'Save the galaxy from a new and massive alien fleet.', 'A modern update with cinematic bosses and power-ups.', 'Space Invaders (USA) features 3D graphics and intense new mechanics. Experience a high-tech evolution of the series that defined a genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-2000-japan', 'Playstation', 'Space Invaders 2000 (Japan)', '2000', 'Shooter', 'Taito', '2', 'Classic arcade shooter', '3D fixed-shooter with enhanced visual effects.', 'Defeat the alien threat in a modernized 2000 edition.', 'A specialized Japanese release with improved performance.', 'Space Invaders 2000 offers more intense waves and polished 32-bit graphics. The definitive way to play the classic on the PS1 in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-x-japan', 'Playstation', 'Space Invaders X (Japan)', '2002', 'Shooter', 'Taito', '2', 'Classic arcade shooter', 'Enhanced 2D fixed-shooter with 3D elements.', 'Repel the alien invasion across multiple planetary sectors.', 'A modernized and flashy update to the Invaders formula.', 'Space Invaders X features cinematic boss battles and branching paths. Experience a high-tech evolution of the arcade legend with stunning 32-bit effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-jam', 'Playstation', 'Space Jam', '1996', 'Sports', 'Acclaim Entertainment', '4', 'Arcade basketball', '3-on-3 arcade basketball based on the hit movie.', 'Win the ultimate game against the Monstars to save the Looney Tunes.', 'A wacky sports game featuring Michael Jordan and Bugs Bunny.', 'Space Jam brings the cinematic crossover to PS1. Use power-ups and Looney Tunes physics to dominate the court in this nostalgic sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spawn---the-eternal-usa', 'Playstation', 'Spawn - The Eternal (USA)', '1997', 'Action', 'Graphic State', '1', 'Action adventure', '3D beat ''em up and exploration based on the comic book.', 'Navigate the dark alleys and Hell to stop a cosmic conspiracy.', 'A gritty action-adventure starring Todd McFarlane''s anti-hero.', 'Spawn - The Eternal features brutal combat and atmospheric exploration. Use Spawn’s supernatural powers to defeat demonic foes in this dark 3D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spec-ops---airborne-commando', 'Playstation', 'Spec Ops - Airborne Commando', '2002', 'Shooter', 'Zipper Interactive', '2', 'Tactical third-person shooter', 'Tactical third-person military shooter.', 'Complete covert airborne missions behind enemy lines.', 'A realistic and punishing budget military simulation.', 'Spec Ops - Airborne Commando focuses on stealth and strategy. Command your squad through hazardous zones in this tactical 32-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spec-ops---covert-assault', 'Playstation', 'Spec Ops - Covert Assault', '2001', 'Shooter', 'Zipper Interactive', '2', 'Tactical third-person shooter', 'Tactical third-person military shooter.', 'Execute high-stakes counter-terrorism operations globally.', 'A mission-based shooter with a focus on realism and team tactics.', 'Spec Ops - Covert Assault challenges players with life-or-like combat scenarios. Manage your resources and outsmart the enemy in this military sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spec-ops---ranger-elite', 'Playstation', 'Spec Ops - Ranger Elite', '2001', 'Shooter', 'Zipper Interactive', '2', 'Tactical third-person shooter', 'Tactical third-person military shooter.', 'Lead an elite ranger unit through various combat theaters.', 'An expanded and improved entry in the Spec Ops series.', 'Spec Ops - Ranger Elite features cooperative play and diverse weaponry. Experience the tension of modern warfare in this strategic action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider---the-video-game-usa', 'Playstation', 'Spider - The Video Game (USA)', '1996', 'Action', 'SingleTrac', '1', 'Action adventure', '2.5D side-scrolling platformer starring a cybernetic spider.', 'Use your robotic limbs to survive a high-tech lab and stop your creator.', 'A unique and creative platformer with multi-planar movement.', 'Spider - The Video Game lets you crawl on walls and ceilings in a 3D space. Use specialized tools to overcome mechanical threats in this hidden gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man', 'Playstation', 'Spider-Man', '2000', 'Action', 'Neversoft', '1', 'Action adventure', '3D action-adventure with web-swinging mechanics.', 'Stop Dr. Octopus and Carnage from unleashing a deadly fog.', 'The definitive 3D superhero experience of its era.', 'Spider-Man features the iconic voice of Stan Lee. Swing through the NYC skyline and battle legendary villains in this landmark Marvel title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-2---enter:-electro', 'Playstation', 'Spider-Man 2 - Enter: Electro', '2001', 'Action', 'Vicarious Visions', '1', 'Action adventure', '3D action-adventure with improved combat and physics.', 'Defeat Electro and prevent him from becoming a god of lightning.', 'A polished and high-energy sequel with new suits and levels.', 'Spider-Man 2 - Enter: Electro expands on the ground-level combat. Face off against the Shocker and Sandman in this action-packed sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spongebob-squarepants---supersponge', 'Playstation', 'SpongeBob SquarePants - SuperSponge', '2001', 'Platformer', 'Heavy Iron Studios', '1', '2D platformer', '2D side-scrolling platformer with a nautical theme.', 'Collect ingredients to make the ultimate Krabby Patty.', 'A charming and funny adventure starring SpongeBob.', 'SuperSponge features vibrant colors and authentic show humor. Explore Bikini Bottom and help your friends in this family-friendly quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-superbike-2', 'Playstation', 'Sports Superbike 2', '2001', 'Racing', 'Milestone', '2', 'Motorcycle racing simulation', 'High-speed motorcycle racing simulation.', 'Win the pro championship on powerful superbikes.', 'A fast-paced and technical bike racer for sports fans.', 'Sports Superbike 2 offers realistic handling and diverse tracks. Master the lean and the throttle to dominate the professional racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spyro-2:-riptos-rage!', 'Playstation', 'Spyro 2: Ripto''s Rage!', '1999', 'Platformer', 'Insomniac Games', '1', '3D platformer', '3D platformer with exploration and mini-games.', 'Collect talismans to help the citizens of Avalar defeat Ripto.', 'An expansive and beloved sequel to the dragon''s debut.', 'Spyro 2: Ripto''s Rage! (Gateway to Glimmer) introduces new abilities like swimming and climbing. Explore vast worlds in this platforming masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spyro-3:-year-of-the-dragon', 'Playstation', 'Spyro 3: Year of the Dragon', '2000', 'Platformer', 'Insomniac Games', '1', '3D platformer', '3D platformer with multiple playable characters.', 'Rescue the stolen dragon eggs from the Sorceress.', 'The final and most content-rich Spyro title on the PS1.', 'Spyro 3: Year of the Dragon features skateboarding, flying, and new allies like Sheila and Bentley. An epic conclusion to the 32-bit trilogy.');
