INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spyro-x-sparx---tondemo-tours-japan', 'Playstation', 'Spyro x Sparx - Tondemo Tours (Japan)', '2001', 'Racing', 'SCE Japan Studio', '1', 'Arcade racing', '3D platformer and mini-game collection for Japan.', 'Complete various challenges with Spyro and his dragonfly friend.', 'A specialized Japanese spin-off of the Spyro series.', 'Spyro x Sparx features creative levels and a focus on the duo''s bond. A rare and charming addition for collectors of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-gladiator---episode-1---final-crusade', 'Playstation', 'Star Gladiator - Episode 1 - Final Crusade', '1996', 'Fighting', 'Capcom', '2', '3D fighting', '3D weapon-based fighting game with a sci-fi theme.', 'Defeat the Bilstein empire in high-stakes space duels.', 'A flashy and technical "soul-like" fighter from Capcom.', 'Star Gladiator features plasma-based combat and cinematic specials. Master the unique weapon styles in this high-energy 3D brawler.');
