INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---invasion-usa', 'Playstation', 'Star Trek - Invasion (USA)', '2000', 'Action', 'Warthog Games', '2', 'Arcade space combat', '3D space combat simulation based on the Star Trek universe.', 'Defend the Federation from a mysterious and ancient threat.', 'A cinematic and action-heavy flight sim with space battles.', 'Star Trek - Invasion features voices from the series cast. Pilot a Valkyrie-class fighter and engage in epic dogfights among the stars.');
