INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('steel-harbinger-usa', 'Playstation', 'Steel Harbinger (USA)', '1996', 'Shooter', 'Visual Concepts', '1', 'Arcade shooter', 'Third-person action-adventure with a sci-fi horror theme.', 'Combat an alien infestation and save the human race.', 'A gritty and violent 3D action game with exploration.', 'Steel Harbinger features massive weapons and dark environments. Fight through mutated hordes to uncover the alien conspiracy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter---the-movie-usa', 'Playstation', 'Street Fighter - The Movie (USA)', '1995', 'Fighting', 'Capcom', '2', '2D fighting', '2D fighting game with digitized live-action actors.', 'Defeat Bison and the Shadaloo forces in the world tournament.', 'A unique fighter based on the movie based on the game!', 'Street Fighter - The Movie features "real" digitized sprites. Experience a different take on the classic brawler with movie-exclusive moves.');
