INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ex-plus-alpha', 'Playstation', 'Street Fighter EX Plus Alpha', '1997', 'Fighting', 'Arika', '2', '3D fighting', '3D fighting game with 2D mechanics and flashy specials.', 'Win the world tournament using massive "Super Combo" chains.', 'The first 3D entry in the Street Fighter series with a unique cast.', 'Street Fighter EX Plus Alpha blends polygonal graphics with classic gameplay. Master "Guard Breaks" and "Excel" combos in this high-energy 3D brawler.');
