INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-zero-japan', 'Playstation', 'Street Fighter Zero (Japan)', '1995', 'Fighting', 'Capcom', '2', '2D fighting', '2D competitive fighting game (Japanese edition).', 'Witness the origins of Ryu and Ken in the "Zero" prequel saga.', 'The original Japanese release of Street Fighter Alpha.', 'Street Fighter Zero features a beautiful anime art style. Master the "Alpha Counter" and "Custom Combo" systems in this landmark 2D hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-zero-2-japan', 'Playstation', 'Street Fighter Zero 2 (Japan)', '1996', 'Fighting', 'Capcom', '2', '2D fighting', '2D competitive fighting game (Japanese edition).', 'Defeat Akuma and master the "Variable Combination" system.', 'The expanded sequel with more characters and deeper mechanics.', 'Street Fighter Zero 2 (Japan) is a masterclass in 2D fighting. Experience the definitive arcade port with pixel-perfect animation and classic gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-zero-3-japan', 'Playstation', 'Street Fighter Zero 3 (Japan)', '1998', 'Fighting', 'Capcom', '2', '2D fighting', '2D competitive fighting game (Japanese edition).', 'Conquer the World Tour mode and defeat the Shadaloo empire.', 'The ultimate version of the Zero/Alpha trilogy on PS1.', 'Street Fighter Zero 3 (Japan) features three distinct fighting styles (Z, V, and X-ISM). Choose from a massive roster in this high-speed brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strider', 'Playstation', 'Strider', '1999', 'Action', 'Capcom', '1', 'Side-scrolling action', '2D side-scrolling action-platformer with a plasma sword.', 'Infiltrate the futuristic city and assassinate Grandmaster Meio.', 'A pixel-perfect port of the legendary 1989 arcade classic.', 'Strider brings high-speed ninja action to the PS1. Scale walls, flip through the air, and cut through robot armies in this cinematic 2.5D hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strider-2-usa', 'Playstation', 'Strider 2 (USA)', '2000', 'Action', 'Capcom', '1', 'Side-scrolling action', '2.5D side-scrolling action-platformer with cinematic bosses.', 'Return to the sky to defeat the resurgent Grandmaster Meio.', 'A fast-paced modern sequel with fluid 3D backgrounds.', 'Strider 2 offers non-stop acrobatic combat and massive mechanical foes. Experience the evolution of the Strider Hiryu legend in this intense action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strikers-1945', 'Playstation', 'Strikers 1945', '1996', 'Shooter', 'Psikyo', '2', 'Vertical shooter', 'Vertical-scrolling 2D "shmup" with WWII-style aircraft.', 'Blast through waves of enemies and defeat transforming bosses.', 'A high-octane arcade shooter from the masters at Psikyo.', 'Strikers 1945 features intense bullet-dodging and powerful sub-weapons. Master the charge shots to survive the futuristic-military onslaught.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suikoden', 'Playstation', 'Suikoden', '1995', 'RPG', 'Konami', '1', 'Japanese RPG', 'Traditional turn-based JRPG with a focus on political intrigue.', 'Recruit the 108 Stars of Destiny to lead a liberation army.', 'A deep and emotional RPG with a massive cast of characters.', 'Suikoden features a unique "Army Battle" system and base building. Lead your forces to victory in this landmark story of betrayal and honor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suikoden-ii', 'Playstation', 'Suikoden II', '1998', 'RPG', 'Konami', '1', 'Japanese RPG', 'Turn-based JRPG with deep story branching and base building.', 'Stop the Highland Empire and navigate a war between best friends.', 'Widely considered one of the greatest JRPGs of all time.', 'Suikoden II offers an unforgettable narrative and tactical combat. Recruit over 100 allies to build your castle and change the fate of the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-rockman-japan-disc-1', 'Playstation', 'Super Adventure Rockman (Japan) (Disc 1)', '1998', 'Adventure', 'Capcom', '1', 'Interactive adventure', 'First-person FMV adventure and shooting game.', 'Stop Dr. Wily''s new threat in a cinematic interactive story.', 'A rare and experimental Mega Man game exclusive to Japan.', 'Super Adventure Rockman (Disc 1) features high-quality anime scenes. Use Mega Man''s buster in a unique first-person perspective to solve the mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-rockman-japan-disc-2', 'Playstation', 'Super Adventure Rockman (Japan) (Disc 2)', '1998', 'Adventure', 'Capcom', '1', 'Interactive adventure', 'First-person FMV adventure and shooting game.', 'Continue the cinematic battle against the Ra Moon super-computer.', 'The second chapter of this obscure 32-bit Mega Man quest.', 'Super Adventure Rockman (Disc 2) ramps up the drama and difficulty. Experience the blue bomber like never before in this interactive anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-rockman-japan-disc-3', 'Playstation', 'Super Adventure Rockman (Japan) (Disc 3)', '1998', 'Adventure', 'Capcom', '1', 'Interactive adventure', 'First-person FMV adventure and shooting game.', 'Reach the final showdown and save the planet from destruction.', 'The climactic finale of the Super Adventure trilogy.', 'Super Adventure Rockman (Disc 3) leads to an epic confrontation. Witness the stunning conclusion to this unique piece of Rockman history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hero-sakusen---diedal-no-yabou-japan', 'Playstation', 'Super Hero Sakusen - Diedal no Yabou (Japan)', '1997', 'Strategy', 'Banpresto', '1', 'Tactical strategy RPG', 'Strategy RPG featuring iconic Japanese superheroes.', 'Lead a team of Ultraman and Gundam heroes to save the world.', 'A massive crossover RPG for fans of Tokusatsu and Mecha.', 'Super Hero Sakusen - Diedal no Yabou features tactical grid combat. Combine the powers of legends to defeat the intergalactic threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hero-sakusen-japan', 'Playstation', 'Super Hero Sakusen (Japan)', '1997', 'Strategy', 'Banpresto', '1', 'Tactical strategy RPG', 'Strategy RPG featuring Ultraman, Kamen Rider, and more.', 'Solve a multiverse crisis involving various anime and live-action icons.', 'A foundational crossover title for the Banpresto hero series.', 'Super Hero Sakusen brings diverse universes together. Master the turn-based strategy and witness epic special moves from classic heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puzzle-fighter-ii-turbo', 'Playstation', 'Super Puzzle Fighter II Turbo', '1996', 'Puzzle', 'Capcom', '2', 'Competitive puzzle fighting', 'Competitive tile-matching puzzle with Street Fighter themes.', 'Defeat rivals by matching colored gems and triggering counters.', 'A hilarious and addictive puzzler with "chibi" Capcom stars.', 'Super Puzzle Fighter II Turbo features chaotic "Drop" patterns. Outsmart your opponent in this colorful and highly competitive puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shot-soccer-usa', 'Playstation', 'Super Shot Soccer (USA)', '1996', 'Sports', 'Impressions Games', '2', 'Arcade soccer', 'Arcade soccer with specialized super-moves and powers.', 'Win the world tournament by using explosive "Super Shots."', 'A wacky and fast-paced soccer game similar to Shaolin Soccer.', 'Super Shot Soccer lets you blast the ball with fire, electricity, and magic. Score spectacular goals in this over-the-top sports brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman-usa-beta-1999-10-29', 'Playstation', 'Superman (USA) (Beta 1999-10-29)', '1999', 'Action', 'Titus Interactive', '1', 'Action adventure', 'Open-world action-adventure featuring the Man of Steel.', 'Solve puzzles and defeat villains in a 3D Metropolis.', 'A rare look at the unreleased PS1 version of the infamous title.', 'Superman (Beta) offers a unique perspective on the hero''s quest. Fly through the city and use your powers in this historical development build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate-wars', 'Playstation', 'Syndicate Wars', '1996', 'Strategy', 'Bullfrog Productions', '2', 'Real-time tactics', 'Tactical isometric action-strategy with a cyberpunk theme.', 'Lead a squad of cyborg agents to achieve global domination.', 'A gritty and violent strategy game from Bullfrog Productions.', 'Syndicate Wars features fully destructible environments and deep research. Control the masses and eliminate rivals in this dark sci-fi sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syphon-filter', 'Playstation', 'Syphon Filter', '1999', 'Action', 'Eidetic', '1', 'Third-person stealth shooter', 'Third-person stealth-action with a focus on gadgets.', 'Infiltrate terrorist bases and neutralize the Syphon Filter virus.', 'A cinematic action game that defined tactical shooting on PS1.', 'Syphon Filter features the iconic Taser and varied mission objectives. Play as Gabe Logan to stop a global biological threat in this 32-bit hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syphon-filter-2', 'Playstation', 'Syphon Filter 2', '2000', 'Action', 'Eidetic', '1', 'Third-person stealth shooter', 'Stealth-action sequel with two playable protagonists.', 'Clear your name and stop the agency conspiracy across the globe.', 'A massive two-disc adventure with improved stealth mechanics.', 'Syphon Filter 2 offers more gadgets and more intense shootouts. Navigate a deep web of betrayal in this high-stakes espionage thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syphon-filter-3', 'Playstation', 'Syphon Filter 3', '2001', 'Action', 'Eidetic', '1', 'Third-person stealth shooter', 'Tactical stealth-action with a mission-based structure.', 'End the biological threat once and for all in a global conflict.', 'The polished conclusion to the Syphon Filter trilogy on PS1.', 'Syphon Filter 3 features more weapons and refined graphics. Complete covert ops in various international locations to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre', 'Playstation', 'Tactics Ogre', '1997', 'Strategy', 'Quest', '1', 'Tactical RPG', 'Tactical turn-based RPG with isometric grid combat.', 'Lead a rebel force to reclaim the throne of Valeria.', 'A legendary strategy masterpiece with branching storylines.', 'Tactics Ogre: Let Us Cling Together offers immense depth and moral choices. Every decision impacts the fate of your army in this hardcore SRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-destiny', 'Playstation', 'Tales of Destiny', '1997', 'RPG', 'Wolf Team', '1', 'Japanese RPG', 'Traditional 2D JRPG with real-time "Linear Motion" combat.', 'Follow Stahn Aileron and his talking sword to save the world.', 'A beautiful and classic entry in the legendary Tales series.', 'Tales of Destiny features vibrant sprite art and a deep story. Experience the fast-paced combat that defined the franchise in this 32-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-destiny-ii-usa-disc-1', 'Playstation', 'Tales of Destiny II (USA) (Disc 1)', '2001', 'RPG', 'Telenet Japan', '1', 'Japanese RPG', 'Epic 2D JRPG with refined real-time combat and exploration.', 'Journey between two parallel worlds to stop a cosmic collapse.', 'A massive three-disc RPG known as Tales of Eternia in Japan.', 'Tales of Destiny II (Disc 1) begins a grand adventure. Master the "Craymel" system and explore a vast world in this stunning JRPG sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-destiny-ii-usa-disc-2', 'Playstation', 'Tales of Destiny II (USA) (Disc 2)', '2001', 'RPG', 'Telenet Japan', '1', 'Japanese RPG', 'Epic 2D JRPG with refined real-time combat and exploration.', 'Uncover the mystery of the Grand Fall and save both realities.', 'The middle chapter of the legendary Tales of Eternia journey.', 'Tales of Destiny II (Disc 2) features deeper character growth and challenging dungeons. Witness the stakes rise in this beautiful 2D masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-destiny-ii-usa-disc-3', 'Playstation', 'Tales of Destiny II (USA) (Disc 3)', '2001', 'RPG', 'Telenet Japan', '1', 'Japanese RPG', 'Epic 2D JRPG with refined real-time combat and exploration.', 'Face the final threat and restore balance to the universe.', 'The emotional and explosive finale of the Eternia saga.', 'Tales of Destiny II (Disc 3) leads to a stunning showdown. Experience the conclusion of one of the PS1''s most polished and beloved JRPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tall---infinity', 'Playstation', 'Tall - Infinity', '1999', 'Action', 'Zoë Mode', '1', 'Stylized action adventure', '3D tower-climbing puzzle game with a sci-fi aesthetic.', 'Move and stack blocks to reach the top of the tower.', 'A unique and addictive 3D puzzler that tests spatial logic.', 'Tall - Infinity features a relaxing atmosphere and challenging levels. Plan your moves carefully to ascend the infinite heights in this cult puzzle hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('team-buddies-usa', 'Playstation', 'Team Buddies (USA)', '2000', 'Strategy', 'Psygnosis', '4', 'Real-time strategy', '3D squad-based action brawler with wacky characters.', 'Lead your team of "Buddies" to defeat rivals in arena combat.', 'A chaotic and funny multiplayer brawler with strategy elements.', 'Team Buddies features unit building and explosive weapons. Dominate the colorful arenas in this unique and hilarious tactical action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tear-ring-saga:-yutona-eiyuu-senki', 'Playstation', 'Tear Ring Saga: Yutona Eiyuu Senki', '2001', 'Strategy', 'Tirnanog', '1', 'Tactical strategy RPG', 'Tactical strategy RPG from the creator of Fire Emblem.', 'Lead two separate armies to save the continent from a dark god.', 'A deep and challenging SRPG with beautiful character designs.', 'Tear Ring Saga offers a classic tactical experience on a grand scale. Manage your troops and navigate a complex tale of war and magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tekken', 'Playstation', 'Tekken', '1994', 'Fighting', 'Namco', '2', '3D fighting', '3D weaponless fighting game with a realistic martial arts style.', 'Win the King of Iron Fist Tournament to claim the Mishima Zaibatsu.', 'The legendary game that launched one of the biggest fighting series.', 'Tekken features a diverse cast of iconic fighters like Kazuya and Paul. Experience the foundation of 3D combat in this arcade-perfect port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tekken-2', 'Playstation', 'Tekken 2', '1995', 'Fighting', 'Namco', '2', '3D fighting', '3D fighting game with expanded rosters and "Tag" elements.', 'Survive the Mishima family betrayal and win the tournament.', 'A massive improvement over the original with cinematic visuals.', 'Tekken 2 features iconic music and technical gameplay. Master the "10-Hit Combos" and unlock secret characters in this all-time classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tekken-3', 'Playstation', 'Tekken 3', '1997', 'Fighting', 'Namco', '2', '3D fighting', '3D fighting game with fluid movement and the "Sidestep" mechanic.', 'Defeat the Ogre and win the ultimate fighting competition.', 'Widely considered the best fighting game on the PlayStation.', 'Tekken 3 features incredible graphics and a huge roster including Jin and Eddy. Experience "Tekken Force" and "Tekken Ball" in this 32-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchu---stealth-assassins-usa', 'Playstation', 'Tenchu - Stealth Assassins (USA)', '1998', 'Action', 'Acquire', '1', 'Stealth action', '3D stealth-action game with an authentic feudal Japan theme.', 'Infiltrate castles as Rikimaru or Ayane to serve Lord Gohda.', 'The game that defined the "Ninja Stealth" genre on PS1.', 'Tenchu - Stealth Assassins features rooftop movement and silent kills. Use a variety of ninja tools to assassinate corrupt lords in this dark quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchu-2---birth-of-the-stealth-assassins-usa', 'Playstation', 'Tenchu 2 - Birth of the Stealth Assassins (USA)', '2000', 'Action', 'Acquire', '1', 'Stealth action', '3D stealth-action with a mission editor.', 'Uncover the origins of the Azuma Ninja and stop the Burning Dawn.', 'A massive prequel with three playable characters and deep stealth.', 'Tenchu 2 - Birth of the Stealth Assassins features fluid swimming, new kills, and a powerful level editor. Master the shadows in this definitive ninja sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tennis', 'Playstation', 'Tennis', '1996', 'Sports', 'Sanritsu', '2', 'Arcade tennis', 'Sports simulation focusing on professional tennis.', 'Win the Grand Slam by mastering serves, volleys, and lobs.', 'A straightforward and accessible tennis game for all ages.', 'Tennis for PS1 offers various court surfaces and tournament modes. Test your reflexes and climb the world rankings in this classic sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('test-drive---off-road-2', 'Playstation', 'Test Drive - Off-Road 2', '1999', 'Racing', 'Accolade', '2', 'Off-road racing', 'Off-road racing simulation with licensed 4x4 vehicles.', 'Dominate treacherous terrains and win the off-road championship.', 'A rugged and muddy racer featuring Hummers and Land Rovers.', 'Test Drive - Off-Road 2 delivers intense 4WD action. Navigate snow, dirt, and sand tracks while outperforming rivals in this high-torque hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-with-card-captor-sakura---eternal-heart-japan', 'Playstation', 'Tetris with Card Captor Sakura - Eternal Heart (Japan)', '1999', 'Puzzle', 'Bullet-Proof Software', '1', 'Tetris-style puzzle', 'Puzzle game blending classic Tetris with anime storytelling.', 'Clear lines to capture Clow Cards and progress through the story.', 'A charming crossover for fans of Cardcaptor Sakura.', 'Tetris with Card Captor Sakura - Eternal Heart features beautiful anime art and unique "Magic" power-ups. Solve puzzles to help Sakura in this Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-adventures-of-lomax', 'Playstation', 'The Adventures of Lomax', '1996', 'Platformer', 'Psygnosis', '1', '2D platformer', '2D side-scrolling platformer with Lemmings-style mechanics.', 'Rescue your friends from the evil Evil Ed and save the land.', 'A visually stunning and colorful spin-off from the Lemmings series.', 'The Adventures of Lomax features smooth animation and challenging levels. Use Lomax''s spinning helmet and abilities in this vibrant platforming quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-italian-job', 'Playstation', 'The Italian Job', '2001', 'Action', 'Rage Software', '1', 'Action driving', 'Mission-based driving game based on the 1969 film.', 'Execute the ultimate gold heist across the streets of Turin.', 'A high-stakes getaway simulator featuring the iconic Mini Cooper.', 'The Italian Job captures the thrill of the classic movie. Navigate narrow alleys and bypass police to pull off the perfect job in this 32-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-king-of-fighters-96', 'Playstation', 'The King of Fighters ''96', '1996', 'Fighting', 'SNK', '2', '2D fighting', '3-on-3 team-based 2D fighting game.', 'Win the global tournament and stop the Orochi threat.', 'A landmark SNK fighter with a massive roster and deep mechanics.', 'The King of Fighters ''96 introduces the series'' iconic "Roll" and "Small Jump" mechanics. Master the Kyo vs. Iori rivalry in this arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-king-of-fighters-97', 'Playstation', 'The King of Fighters ''97', '1997', 'Fighting', 'SNK', '2', '2D fighting', '3-on-3 team-based 2D fighting game.', 'Defeat the Orochi clan in the final showdown of the saga.', 'One of the most beloved entries in the KOF series.', 'The King of Fighters ''97 features "Advanced" and "Extra" fighting styles. Experience the epic conclusion to the Orochi storyline with pixel-perfect sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-king-of-fighters-98', 'Playstation', 'The King of Fighters ''98', '1998', 'Fighting', 'SNK', '2', '2D fighting', '3-on-3 team-based 2D fighting game.', 'Prove your skills in the ultimate "Dream Match" tournament.', 'A massive compilation of characters from the first four games.', 'The King of Fighters ''98 is widely considered the most balanced entry. Enjoy non-stop fighting action with an incredible roster of SNK legends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-king-of-fighters-99', 'Playstation', 'The King of Fighters ''99', '1999', 'Fighting', 'SNK', '2', '2D fighting', '4-on-4 team-based 2D fighting game with "Strikers."', 'Investigate the NESTS cartel and master the new assist system.', 'The beginning of the NESTS saga with tactical 4th-man mechanics.', 'The King of Fighters ''99 introduces K'' and the Striker system. Refine your strategy and unleash devastating team combos in this deep brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('theme-hospital', 'Playstation', 'Theme Hospital', '1997', 'Simulation', 'Bullfrog Productions', '1', 'Hospital management simulation', 'Medical-themed management and business simulation.', 'Design and run a successful hospital while curing bizarre diseases.', 'A humorous and addictive tycoon game from Bullfrog.', 'Theme Hospital challenges you to cure "Bloated Head" and "Elvis Syndrome." Manage staff and build a medical empire in this comedy-sim classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('theme-park', 'Playstation', 'Theme Park', '1995', 'Simulation', 'Bullfrog Productions', '1', 'Theme park management', 'Amusement park management and strategy simulation.', 'Build the world''s greatest theme park and keep guests happy.', 'The foundational tycoon game for the 32-bit era.', 'Theme Park lets you design rollercoasters and balance your park''s finances. A deep and rewarding sim that puts your management skills to the test.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thrasher:-skate-and-destroy', 'Playstation', 'Thrasher: Skate and Destroy', '1999', 'Sports', 'Z-Axis', '2', 'Skateboarding', 'Urban skateboarding simulation with a focus on realism.', 'Master technical tricks and outrun the cops in street sessions.', 'A gritty, street-level alternative to the Tony Hawk series.', 'Thrasher: Skate and Destroy features realistic physics and a hardcore hip-hop soundtrack. Prove your skills in the most authentic skate sim on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('threads-of-fate', 'Playstation', 'Threads of Fate', '1999', 'RPG', 'Square', '1', 'Action RPG', 'Action-RPG with two distinct storylines and protagonists.', 'Search for the "Dew Prism" to grant your greatest wish.', 'A charming and visually unique JRPG from Square.', 'Threads of Fate (Dew Prism) features two playstyles: Rue''s shapeshifting or Mint''s magic. Experience a whimsical and emotional adventure in this cult hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('three-stooges-the-usa', 'Playstation', 'Three Stooges, The (USA)', '2000', 'Platformer', 'Video System', '2', 'Arcade platformer', 'Mini-game collection based on the classic comedy trio.', 'Complete slapstick challenges to save the local orphanage.', 'A nostalgic and funny variety game featuring Larry, Moe, and Curly.', 'The Three Stooges brings the classic shorts to life with digital voices and iconic humor. Solve puzzles and win mini-games in this retro tribute.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thrill-kill-usa-beta', 'Playstation', 'Thrill Kill (USA) (Beta)', '1998', 'Fighting', 'Paradox Development', '2', 'Adult fighting', '4-player arena fighting game with a dark, gore-heavy theme.', 'Battle in a supernatural purgatory to earn a second chance at life.', 'An infamous, unreleased brawler known for its extreme violence.', 'Thrill Kill features brutal kills and unique four-way combat. Play this piece of gaming history and witness the darkness of the "lost" PS1 fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-storm-&-road-blaster-japan-disc-1-thunder-storm', 'Playstation', 'Thunder Storm & Road Blaster (Japan) (Disc 1) (Thunder Storm)', '1989', 'Shooter', 'Data East', '1', 'Rail shooter', 'FMV-based aerial combat rail-shooter.', 'Pilot a high-tech fighter to repel an alien invasion.', 'A cinematic arcade port of the classic Laserdisc hit.', 'Thunder Storm features hand-drawn anime visuals and intense dogfights. Experience the thrill of 80s arcade action in this immersive flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-storm-&-road-blaster-japan-disc-2-road-blaster', 'Playstation', 'Thunder Storm & Road Blaster (Japan) (Disc 2) (Road Blaster)', '1989', 'Shooter', 'Data East', '1', 'Rail shooter', 'FMV-based vehicular combat and pursuit game.', 'Drive a high-performance car to stop a criminal organization.', 'The cinematic sequel to Thunder Storm with a focus on car chases.', 'Road Blaster (Disc 2) delivers high-speed anime action. Navigate treacherous roads and ram enemies in this interactive animated thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-truck-rally', 'Playstation', 'Thunder Truck Rally', '1997', 'Racing', 'Electronic Arts', '2', 'Arcade truck racing', 'Monster truck racing with destructible environments.', 'Win the championship by crushing cars and outspeeding rivals.', 'A loud and chaotic racer featuring massive 4x4 machines.', 'Thunder Truck Rally (Monster Trucks) offers high-energy stadium racing. Choose your beast and dominate the dirt in this explosive 32-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiggers-honey-hunt', 'Playstation', 'Tigger''s Honey Hunt', '2000', 'Platformer', 'Digital Eclipse', '1', 'Platform adventure', '3D platformer and mini-game collection for kids.', 'Help Tigger find honey for Winnie the Pooh''s party.', 'A gentle and colorful adventure set in the 100 Acre Wood.', 'Tigger''s Honey Hunt is perfect for young players. Bounce through vibrant levels and complete fun tasks with the most energetic tiger around.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-bokan-series---bokan-desu-yo-japan', 'Playstation', 'Time Bokan Series - Bokan desu yo (Japan)', '1996', 'Action', 'Tatsunoko', '2', 'Arcade action', 'Comedic aerial combat shooter based on the anime series.', 'Pilot wacky mechs to defeat the Doronbo Gang.', 'A colorful and funny "shmup" featuring the iconic villains.', 'Bokan desu yo captures the humor of the Time Bokan franchise. Enjoy high-energy shooting and funny dialogues in this Japanese arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-bokan-series---bokan-to-ippatsu!-doronbow-japan', 'Playstation', 'Time Bokan Series - Bokan to Ippatsu! Doronbow (Japan)', '1997', 'Action', 'Tatsunoko', '2', 'Arcade action', 'Comedic racing and action game featuring the Doronbo Gang.', 'Race through time to find the legendary "Dokuro Stone."', 'A wacky and diverse adventure with mini-games and mechs.', 'Bokan to Ippatsu! Doronbow features the beloved trio of villains. Experience the charm of the anime in this varied and funny 32-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-crisis', 'Playstation', 'Time Crisis', '1995', 'Shooter', 'Namco', '1', 'Light gun shooter', 'Light-gun shooting gallery with cinematic action.', 'Stop the Wild Dog syndicate with precision shooting and cover.', 'The landmark game that defined the light-gun genre.', 'Time Crisis features the iconic "Duck" mechanic. Use the Guncon to blast through enemies in this high-intensity, pulse-pounding arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timeless-jade-trade', 'Playstation', 'Timeless Jade Trade', '1996', 'Educational', 'Edmark', '1', 'Educational trading', 'Educational strategy and trading simulation.', 'Manage resources and trade goods in an ancient setting.', 'A learning-focused game designed for schools.', 'Timeless Jade Trade teaches economic principles through interactive gameplay. Build your trade empire in this rare educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timeless-math-7---rover-recovery', 'Playstation', 'Timeless Math 7 - Rover Recovery', '1998', 'Educational', 'Edmark', '1', 'Educational math', 'Educational math-based adventure.', 'Solve complex math problems to recover the Mars rover.', 'A challenging learning game for middle-school students.', 'Timeless Math 7 - Rover Recovery makes mathematics engaging. Use logic and arithmetic to save the mission in this educational sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tintin---destination-adventure-europe-enfrdeesitnlpt', 'Playstation', 'Tintin - Destination Adventure (Europe) (En,Fr,De,Es,It,Nl,Pt)', '1996', 'Adventure', 'Ellipse', '1', 'Graphic adventure', '3D action-adventure based on the famous comic series.', 'Join Tintin and Snowy on an epic journey to the Moon.', 'A cinematic quest with puzzles, platforming, and vehicles.', 'Tintin - Destination Adventure follows the classic albums. Explore diverse international locations in this faithful and charming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---pluckys-big-adventure', 'Playstation', 'Tiny Toon Adventures - Plucky''s Big Adventure', '1999', 'Platformer', 'Konami', '1', '3D platformer', '2D side-scrolling platformer starring Plucky Duck.', 'Help Plucky find the items he needs for his "big adventure."', 'A colorful and funny platformer for fans of Tiny Toons.', 'Plucky''s Big Adventure features classic cartoon humor and tight controls. Navigate ACME Looniversity in this family-friendly 32-bit hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---the-great-beanstalk-usa', 'Playstation', 'Tiny Toon Adventures - The Great Beanstalk (USA)', '1998', 'Platformer', 'Konami', '1', 'Platform adventure', 'Adventure and puzzle game based on the Jack and the Beanstalk tale.', 'Climb the beanstalk and recover the treasures from the giant.', 'A charming variety game for younger players.', 'The Great Beanstalk features mini-games and exploration. Help Buster and the gang in this educational and entertaining Tiny Toons quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---toonenstein---dare-to-scare!-usa', 'Playstation', 'Tiny Toon Adventures - Toonenstein - Dare to Scare! (USA)', '1999', 'Platformer', 'Konami', '1', 'Action platformer', '3D adventure with a spooky, cartoon theme.', 'Explore a haunted mansion to rescue your friends from Toonenstein.', 'A lighthearted "horror" adventure for kids.', 'Toonenstein - Dare to Scare! features puzzles and exploration. Outsmart the monsters in this vibrant and funny Tiny Toons adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-and-jerry-in-house-trap', 'Playstation', 'Tom and Jerry in House Trap', '2000', 'Platformer', 'Beam Software', '1', 'Puzzle platformer', 'Isometric action-puzzle game featuring the iconic duo.', 'Set traps around the house to outsmart your rival.', 'A strategic and funny brawler for one or two players.', 'Tom and Jerry in House Trap captures the slapstick humor of the cartoons. Use household items to win the ultimate cat-and-mouse game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-rainbow-six---lone-wolf', 'Playstation', 'Tom Clancy''s Rainbow Six - Lone Wolf', '2002', 'Shooter', 'Red Storm Entertainment', '1', 'Tactical shooter', 'Tactical squad-based first-person shooter.', 'Lead an elite operative on high-stakes solo stealth missions.', 'A more focused and personal entry in the Rainbow Six series.', 'Lone Wolf features realistic ballistics and tactical planning. Navigate dangerous environments as a one-man army in this military sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomb-raider-usa', 'Playstation', 'Tomb Raider (USA)', '1996', 'Action', 'Core Design', '1', 'Action adventure', '3D action-adventure with platforming and exploration.', 'Find the pieces of the Scion in ancient ruins across the globe.', 'The landmark game that introduced the world to Lara Croft.', 'Tomb Raider redefined 3D exploration. Solve massive environmental puzzles and survive dangerous predators in this legendary classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomb-raider-2', 'Playstation', 'Tomb Raider 2', '1997', 'Action', 'Core Design', '1', 'Action adventure', '3D action-adventure with vehicles and diverse locations.', 'Recover the Dagger of Xian from the Great Wall to Venice.', 'A massive sequel with more action and larger levels.', 'Tomb Raider 2 features Lara in diverse outfits and locations. Master the parkour and gunplay in this definitive 32-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomba!', 'Playstation', 'Tomba!', '1998', 'Platformer', 'Whoopee Camp', '1', 'Action platformer RPG', '2D side-scrolling platformer with RPG and quest elements.', 'Defeat the Seven Evil Pigs to restore peace to the land.', 'A colorful, unique, and highly-acclaimed "Metroidvania."', 'Tomba! (Tombi!) features a unique quest system and vibrant art. Use your strength to clear the world of the pig curse in this cult masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomba!-2:-the-evil-swine-return', 'Playstation', 'Tomba! 2: The Evil Swine Return', '2001', 'Platformer', 'Whoopee Camp', '1', 'Action platformer RPG', '3D side-scrolling platformer with deep quest mechanics.', 'Rescue your girlfriend and defeat the resurgent Evil Pigs.', 'An ambitious sequel that transitions the series into 3D.', 'Tomba! 2: The Evil Swine Return (Tombi! 2) features a variety of suits and powers. Explore a world filled with secrets and clever puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater', 'Playstation', 'Tony Hawk''s Pro Skater', '1999', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Arcade skateboarding with technical tricks and combos.', 'Complete goals and achieve high scores in iconic skate parks.', 'The game that revolutionized the extreme sports genre.', 'Tony Hawk''s Pro Skater features a legendary soundtrack and fluid controls. Master the kickflip and grind your way to victory in this 32-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-2', 'Playstation', 'Tony Hawk''s Pro Skater 2', '2000', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Arcade skateboarding with a focus on manual balance.', 'Unlock new skaters and levels by completing professional goals.', 'Widely considered the greatest skateboarding game ever made.', 'Tony Hawk''s Pro Skater 2 introduces the "Manual" for infinite combos. Custom build your own skater and park in this masterpiece of action sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-3', 'Playstation', 'Tony Hawk''s Pro Skater 3', '2001', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Arcade skateboarding with high-speed combo mechanics.', 'Shred through diverse international levels to earn gold medals.', 'A polished and content-rich entry in the legendary series.', 'Tony Hawk''s Pro Skater 3 features the "Revert" for massive vertical combos. Experience the peak of arcade skating with a huge pro roster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-4', 'Playstation', 'Tony Hawk''s Pro Skater 4', '2002', 'Sports', 'Neversoft', '2', 'Skateboarding', 'Arcade skateboarding with an open-ended mission structure.', 'Complete pro challenges and explore large interactive worlds.', 'The final Tony Hawk entry for the original PlayStation.', 'Tony Hawk''s Pro Skater 4 offers a non-linear career mode. Master the technical tricks and dominate the streets in this refined skating sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-2---buzz-lightyear-to-the-rescue', 'Playstation', 'Toy Story 2 - Buzz Lightyear to the rescue', '1999', 'Platformer', 'Traveller''s Tales', '1', '3D platformer', '3D action-platformer featuring the iconic Space Ranger.', 'Rescue Woody and defeat Zurg across movie-inspired levels.', 'A vibrant and faithful 3D adventure based on the Pixar hit.', 'Toy Story 2: Buzz Lightyear to the Rescue! features gadgets and puzzles. Explore Andy''s House and Al''s Toy Barn in this family-favorite classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-goddesses', 'Playstation', 'Twin Goddesses', '1995', 'RPG', 'Fill-in-Cafe', '1', 'Anime RPG', '2D fighting game with digitized actors and FMV elements.', 'Defeat rival warriors in a high-stakes fantasy tournament.', 'A unique and rare Japanese fighter with a cinematic feel.', 'Twin Goddesses combines traditional brawling with live-action visuals. Experience the charm of early 32-bit experimental design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twinbee-rpg', 'Playstation', 'TwinBee-RPG', '1998', 'RPG', 'Konami', '1', 'Lighthearted RPG', 'Turn-based JRPG featuring the TwinBee universe.', 'Join Light and Pastel on a grand quest to save Donburi Island.', 'A colorful and charming departure for the classic shooter series.', 'TwinBee-RPG features traditional turn-based combat and a wholesome story. Explore a vibrant world in this rare Japanese role-playing gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-metal', 'Playstation', 'Twisted Metal', '1995', 'Action', 'SingleTrac', '2', 'Vehicular combat', 'Vehicular combat with weaponized cars and arenas.', 'Win the Twisted Metal tournament to grant your deepest wish.', 'The dark and chaotic beginning of the car combat genre.', 'Twisted Metal features iconic characters like Sweet Tooth. Blast your rivals with missiles and mines in this high-octane 3D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-metal---small-brawl', 'Playstation', 'Twisted Metal - Small Brawl', '2001', 'Action', 'Incognito Entertainment', '4', 'Vehicular combat', 'Vehicular combat featuring RC cars in domestic settings.', 'Outsmart your rivals in backyard and kitchen-themed arenas.', 'A creative and lighthearted spin on the Twisted Metal formula.', 'Twisted Metal: Small Brawl takes the carnage to a smaller scale. Drive miniature weaponized toys in this fun and chaotic arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-metal-2', 'Playstation', 'Twisted Metal 2', '1996', 'Action', 'SingleTrac', '2', 'Vehicular combat', 'Vehicular combat with global arenas and improved physics.', 'Destroy the competition across the world''s most famous cities.', 'The definitive vehicular combat experience on the PS1.', 'Twisted Metal 2 (World Tour) features iconic levels like Paris and LA. Master the special moves and dominate the ultimate demolition derby.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-metal-3', 'Playstation', 'Twisted Metal 3', '1998', 'Action', '989 Studios', '2', 'Vehicular combat', 'Vehicular combat with a heavy emphasis on 3D graphics.', 'Win Calypso''s tournament in a new era of automotive carnage.', 'A flashy and explosive entry with a high-energy soundtrack.', 'Twisted Metal 3 introduces new physics and destructive environments. Choose from a diverse cast of drivers and blast your way to the top.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-metal-4', 'Playstation', 'Twisted Metal 4', '1999', 'Action', '989 Studios', '2', 'Vehicular combat', 'Vehicular combat with deep customization and team play.', 'Overthrow Calypso and take control of the Twisted Metal contest.', 'The final standard entry for the series on the original hardware.', 'Twisted Metal 4 features a "Create-a-Car" mode and massive bosses. Experience the peak of 32-bit vehicular mayhem in this action-heavy hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-underworld---the-stygian-abyss', 'Playstation', 'Ultima Underworld - The Stygian Abyss', '1997', 'RPG', 'Looking Glass Studios', '1', 'First-person dungeon RPG', 'First-person dungeon-crawling RPG.', 'Survive the depths of the Stygian Abyss and rescue a princess.', 'A legendary immersive sim adapted for the PlayStation.', 'Ultima Underworld offers deep exploration and complex interactions. Navigate a dark 3D underworld in this influential fantasy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultraman---fighting-evolution-japan', 'Playstation', 'Ultraman - Fighting Evolution (Japan)', '1999', 'Fighting', 'Bandai', '2', '3D fighting', '3D fighting game based on the iconic Japanese hero.', 'Defeat giant monsters and aliens to protect the Earth.', 'A high-energy brawler for fans of the Ultraman franchise.', 'Ultraman - Fighting Evolution features cinematic specials and giant mechs. Master the martial arts of the Ultra-Crusaders in this Japanese hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('um-jammer-lammy-europe-enfrdeesit', 'Playstation', 'Um Jammer Lammy (Europe) (En,Fr,De,Es,It)', '1999', 'Music', 'NanaOn-Sha', '1', 'Rhythm game', 'Rhythm-based music game featuring a rock-star lamb.', 'Play the guitar to the beat to overcome various life challenges.', 'The stylish and groovy spin-off to PaRappa the Rapper.', 'Um Jammer Lammy (Europe) features catchy rock tunes and surreal art. Follow Lammy''s journey to her concert in this rhythmic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('um-jammer-lammy-usa', 'Playstation', 'Um Jammer Lammy (USA)', '1999', 'Music', 'NanaOn-Sha', '1', 'Rhythm game', 'Rhythm-based music game with a focus on guitar riffs.', 'Match the rhythm to help Lammy get to her gig on time.', 'A vibrant and quirky music game with a punk-rock attitude.', 'Um Jammer Lammy (USA) delivers non-stop beats and colorful visuals. "Leave it to Lammy!" and rock out in this iconic PlayStation title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('unholy-war-the', 'Playstation', 'Unholy War, The', '1998', 'Action', 'Toybox', '2', 'Action strategy', 'Tactical strategy-action hybrid with a fantasy theme.', 'Lead your chosen faction to victory in hexagonal grid combat.', 'A unique and intense blend of strategy and 3D brawling.', 'The Unholy War features diverse units with unique special attacks. Strategize on the map and fight for real in the arena in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('v2000', 'Playstation', 'V2000', '1997', 'Racing', 'Cavedog Entertainment', '2', 'Futuristic racing', '3D flight-action game based on the Virus universe.', 'Pilot a high-tech craft to eliminate the alien infestation.', 'A fast-paced and visually impressive sequel to "Virus."', 'V2000 features smooth 3D flight and intense shooting. Navigate alien landscapes and destroy the viral threat in this sci-fi adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vagrant-story', 'Playstation', 'Vagrant Story', '2000', 'RPG', 'Square', '1', 'Action RPG', 'Deep tactical action-RPG with a focus on weapon crafting.', 'Investigate the ruins of Lea Monde as a Riskbreaker.', 'A cinematic masterpiece from the creators of Final Fantasy Tactics.', 'Vagrant Story features a unique localized damage system and a dark plot. Explore a haunting gothic world in this critically acclaimed epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vampire-hunter-d-usa', 'Playstation', 'Vampire Hunter D (USA)', '2000', 'Action', 'Victor Interactive Software', '1', 'Anime action adventure', '3D action-adventure based on the vampire-hunting anime.', 'Infiltrate the castle of the vampire lord and rescue the captives.', 'A dark and atmospheric quest with sword-play and puzzles.', 'Vampire Hunter D features the iconic gothic hero in a 32-bit world. Use your supernatural abilities to survive the nightmarish castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vandal-hearts---ushinawareta-kodai-bunmei-japan', 'Playstation', 'Vandal Hearts - Ushinawareta Kodai Bunmei (Japan)', '1996', 'Strategy', 'Konami', '1', 'Tactical RPG', 'Tactical turn-based RPG with isometric grid combat.', 'Lead a band of rebels to uncover the truth of a lost civilization.', 'The original Japanese release of the tactical classic.', 'Vandal Hearts (Japan) features brutal combat and a deep narrative. Master the strategic positioning of your units to win the war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vandal-hearts-usa', 'Playstation', 'Vandal Hearts (USA)', '1997', 'Strategy', 'Konami', '1', 'Tactical RPG', 'Tactical turn-based RPG with visceral combat and blood.', 'Restore order to a kingdom torn apart by corruption and war.', 'A gritty and challenging strategy RPG for the PS1.', 'Vandal Hearts features diverse character classes and a gripping story. Lead the "Church of the Restoration" in this landmark 32-bit sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vandal-hearts-ii', 'Playstation', 'Vandal Hearts II', '1999', 'Strategy', 'Konami', '1', 'Tactical RPG', 'Tactical turn-based RPG with simultaneous movement.', 'Navigate a dark tale of betrayal and war across two nations.', 'A deep and complex sequel with a unique combat system.', 'Vandal Hearts II features a "Dual Turn" system where units move at once. Experience a mature and political story in this strategy masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vandal-hearts-ii---tenjou-no-mon-japan', 'Playstation', 'Vandal Hearts II - Tenjou no Mon (Japan)', '1999', 'Strategy', 'Konami', '1', 'Tactical RPG', 'Tactical turn-based RPG (Japanese edition).', 'Follow Joshua and Rosaly through a world of shadows and steel.', 'The original Japanese version of the ambitious Vandal sequel.', 'Vandal Hearts II (Japan) offers tactical depth and a branching plot. Master the innovative combat mechanics in this epic 32-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vandal-hearts-ii-usa', 'Playstation', 'Vandal Hearts II (USA)', '1999', 'Strategy', 'Konami', '1', 'Tactical RPG', 'Tactical turn-based RPG with deep story and strategy.', 'Survive the chaos of the "Door of Heaven" conflict.', 'The North American release of the technical strategy sequel.', 'Vandal Hearts II features massive tactical battles and a dark tone. Every move counts in this sophisticated and emotional RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vib-ribbon', 'Playstation', 'Vib Ribbon', '1999', 'Music', 'NanaOn-Sha', '1', 'Rhythm game', 'Rhythm-based game where the world is built from your music.', 'Guide Vibri through 2D obstacle courses created by audio tracks.', 'A minimalist and revolutionary experimental music game.', 'Vib-Ribbon features a unique vector-art style and the ability to use your own CDs. Experience the most rhythmic challenge on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8---2nd-offense-usa', 'Playstation', 'Vigilante 8 - 2nd Offense (USA)', '1999', 'Action', 'Luxoflux', '2', 'Vehicular combat', 'Vehicular combat with 1970s style and specialized weapons.', 'Defeat the Coyotes and save the future from a temporal threat.', 'A groovy and explosive sequel with transforming vehicles.', 'Vigilante 8 - 2nd Offense features missions on land, sea, and air. Blast through the 70s in this high-octane car combat hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-8-usa', 'Playstation', 'Vigilante 8 (USA)', '1998', 'Action', 'Luxoflux', '2', 'Vehicular combat', 'Vehicular combat with destructible environments and gadgets.', 'Win the war on the American highways with weaponized cars.', 'A stylish and intense alternative to Twisted Metal.', 'Vigilante 8 features a funky soundtrack and unique "Total Audio" tech. Use physics-based combat to wreck your rivals in this classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-pool-3', 'Playstation', 'Virtual Pool 3', '2000', 'Sports', 'Celeris', '2', 'Pool simulation', 'Realistic 3D pool and billiards simulation.', 'Compete in professional tournaments and master the table.', 'The most technical and accurate pool game for the console.', 'Virtual Pool 3 offers precise physics and various game modes. Learn the art of the cue and win the championship in this sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vr-soccer-96', 'Playstation', 'VR Soccer ''96', '1996', 'Sports', 'Silicon Dreams Studio', '2', 'Soccer', '3D soccer simulation with a focus on immersive visuals.', 'Lead your international team to victory in the World Cup.', 'An early and ambitious 3D football game for the PS1.', 'VR Soccer ''96 features multiple camera angles and realistic motion. Experience the beautiful game in a 32-bit virtual stadium.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vs', 'Playstation', 'Vs.', '1997', 'Fighting', 'Psikyo', '2', 'Arcade fighting', '2D/3D fighting game collection and mini-games.', 'Defeat your opponents in various competitive modes.', 'A diverse variety game focusing on "Versus" gameplay.', 'Vs. features a mix of genres and styles for competitive fans. Challenge your friends to a series of skill-based mini-games and fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waku-puyo-dungeon---ketteiban-japan', 'Playstation', 'Waku Puyo Dungeon - Ketteiban (Japan)', '1998', 'RPG', 'Compile', '1', 'Dungeon RPG', '3D dungeon-crawling RPG with Puyo Puyo characters.', 'Navigate procedural mazes to find treasure and defeat bosses.', 'A charming and colorful "Roguelike" set in the Puyo world.', 'Waku Puyo Dungeon features Arle and Car-kun in a quest for loot. Master the tactical combat and escape the dungeon in this Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('walt-disney-world-quest---magical-racing-tour-usa', 'Playstation', 'Walt Disney World Quest - Magical Racing Tour (USA)', '2000', 'Racing', 'Eidos Interactive', '4', 'Arcade kart racing', 'Kart racing featuring various Disney movie characters.', 'Win the Magical Racing Tour across iconic Disney attractions.', 'A fun and nostalgic racer set in Disney World parks.', 'Walt Disney World Quest features tracks like Splash Mountain. Collect coins and use magical power-ups in this family-friendly racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wargames---defcon-1-usa', 'Playstation', 'WarGames - Defcon 1 (USA)', '1998', 'Strategy', 'The 3DO Company', '1', 'Real-time strategy', 'Real-time tactical strategy and vehicular combat.', 'Defend the US or the NORAD computer from a global threat.', 'A unique strategy game based on the classic 80s movie.', 'WarGames: Defcon 1 features two distinct campaigns and team play. Control tanks and jets to dominate the battlefield in this sci-fi sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzkys-3d-hockey-98', 'Playstation', 'Wayne Gretzky''s 3D Hockey ''98', '1998', 'Sports', 'Midway', '4', 'Arcade hockey', '3D arcade hockey featuring the legendary "Great One."', 'Score spectacular goals and win the championship on ice.', 'A fast, hard-hitting, and arcade-style hockey game.', 'Wayne Gretzky''s 3D Hockey ''98 features massive hits and fire-goals. Experience the high-energy excitement of the NHL in this sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-mayhem', 'Playstation', 'WCW Mayhem', NULL, NULL, NULL, NULL, NULL, '3D professional wrestling with backstage fighting.', 'Win the WCW World Heavyweight Championship.', 'A fast-paced wrestling game featuring Nitro arenas.', 'WCW Mayhem brings the Monday Night Wars to your home. Fight in the ring or take the brawl to the back in this hard-hitting sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-arms-usa', 'Playstation', 'Wild Arms (USA)', NULL, NULL, NULL, NULL, NULL, 'Traditional turn-based JRPG with a "Wild West" fantasy theme.', 'Help Rudy, Jack, and Cecilia save the world of Filgaia.', 'A legendary RPG known for its unique setting and soundtrack.', 'Wild Arms blends western aesthetics with classic JRPG mechanics. Solve environmental puzzles and master "ARMS" in this 32-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('williams-arcades-greatest-hits', 'Playstation', 'Williams Arcade''s Greatest Hits', NULL, NULL, NULL, NULL, NULL, 'Compilation of legendary arcade classics.', 'Relive the golden age of gaming with pixel-perfect ports.', 'Featuring Joust, Defender, Robotron, and more.', 'Williams Arcade''s Greatest Hits is a time capsule of retro fun. Master the high scores of the most influential arcade games in history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wipeout-2097', 'Playstation', 'Wipeout 2097', NULL, NULL, NULL, NULL, NULL, 'Futuristic anti-gravity racing with weapons.', 'Win the F5000 league across high-speed tracks.', 'The high-octane European sequel to the racing phenomenon.', 'Wipeout 2097 (Wipeout XL) features a killer soundtrack and intense speed. Experience the peak of futuristic racing on the PlayStation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wipeout-3---special-edition-europe-enfrdeesit', 'Playstation', 'Wipeout 3 - Special Edition (Europe) (En,Fr,De,Es,It)', NULL, NULL, NULL, NULL, NULL, 'Refined anti-gravity racing with more content.', 'Dominate the tracks in the most complete Wipeout experience.', 'The definitive European edition with bonus tracks and crafts.', 'Wipeout 3 - Special Edition offers sleek visuals and precise handling. Includes classic tracks from previous games in high resolution.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wipeout-3-usa', 'Playstation', 'Wipeout 3 (USA)', NULL, NULL, NULL, NULL, NULL, 'Futuristic anti-gravity racing with a minimalist aesthetic.', 'Master the corners and use weapons to outpace the competition.', 'A stylish and high-speed racing masterpiece.', 'Wipeout 3 features a clean, high-tech design and intense combat. Race through futuristic cityscapes at breakneck speeds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wipeout-xl-usa', 'Playstation', 'Wipeout XL (USA)', NULL, NULL, NULL, NULL, NULL, 'Futuristic anti-gravity racing with weapons.', 'Conquer the global racing circuit in the year 2097.', 'The North American version of the iconic Wipeout sequel.', 'Wipeout XL delivers pure adrenaline and electronic beats. Blast rivals with missiles while navigating gravity-defying tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('woody-woodpecker-racing', 'Playstation', 'Woody Woodpecker Racing', NULL, NULL, NULL, NULL, NULL, '3D kart racing featuring the classic cartoon cast.', 'Win the race using wacky weapons and character abilities.', 'A fun and colorful racer starring Woody Woodpecker.', 'Woody Woodpecker Racing offers diverse tracks and funny animations. Perfect for younger players and fans of the classic cartoons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('worlds-scariest-police-chases', 'Playstation', 'World''s Scariest Police Chases', NULL, NULL, NULL, NULL, NULL, 'Mission-based driving and pursuit simulation.', 'Chase down criminals and execute "Pit" maneuvers.', 'A gritty action-driving game narrated by John Bunnell.', 'World''s Scariest Police Chases puts you behind the wheel of a patrol car. Stop the most dangerous drivers in this high-stakes thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wu-tang---shaolin-style', 'Playstation', 'Wu-Tang - Shaolin Style', NULL, NULL, NULL, NULL, NULL, '4-player arena brawler featuring the legendary rap group.', 'Defeat the shadow syndicate using Shaolin martial arts.', 'A violent and atmospheric fighter with a Wu-Tang soundtrack.', 'Wu-Tang - Shaolin Style (Taste the Fury) features unique fighting styles for each member. Battle in 4-way arenas in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-in-your-house', 'Playstation', 'WWF In Your House', NULL, NULL, NULL, NULL, NULL, 'Arcade-style wrestling with over-the-top special moves.', 'Dominate the ring in a stylized, exaggerated WWF world.', 'A fast and wacky take on pro wrestling.', 'WWF In Your House features "superhuman" moves and interactive arenas. Play as Bret Hart or Shawn Michaels in this arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-smackdown!', 'Playstation', 'WWF SmackDown!', NULL, NULL, NULL, NULL, NULL, '3D professional wrestling with a massive season mode.', 'Rise through the ranks to become the WWF Champion.', 'The game that revolutionized wrestling on the PlayStation.', 'WWF SmackDown! features fast gameplay and a deep "Create-a-Wrestler" mode. Experience the thrill of the Attitude Era in this classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-smackdown!-2', 'Playstation', 'WWF SmackDown! 2', NULL, NULL, NULL, NULL, NULL, '3D professional wrestling with expanded backstage areas.', 'Rule the ring and survive the chaotic "Know Your Role" season.', 'Widely considered the best wrestling game on the PS1.', 'WWF SmackDown! 2 features a huge roster and "Hell in a Cell" matches. Master the technical grappling and win the title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-war-zone-usa', 'Playstation', 'WWF War Zone (USA)', NULL, NULL, NULL, NULL, NULL, '3D professional wrestling with a focus on realism.', 'Win the belt in a gritty and technical wrestling environment.', 'The first 3D WWF title with a deep "Create-a-Wrestler."', 'WWF War Zone features authentic promos and hard-hitting action. Master the complex move sets to dominate your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania---the-arcade-game', 'Playstation', 'WWF WrestleMania - The Arcade Game', NULL, NULL, NULL, NULL, NULL, '2D arcade wrestling with supernatural special moves.', 'Win the tournament in a "Mortal Kombat" style wrestling game.', 'An over-the-top arcade classic with digitized sprites.', 'WWF WrestleMania brings high-energy spectacle to the ring. Use magical attacks and combos in this unique sports-action hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---mutant-academy-usa', 'Playstation', 'X-Men - Mutant Academy (USA)', NULL, NULL, NULL, NULL, NULL, '3D weaponless fighting game featuring Marvel''s mutants.', 'Train your skills and defeat rivals in the Danger Room.', 'A technical 3D fighter with cinematic finishing moves.', 'X-Men - Mutant Academy features iconic characters like Wolverine and Cyclops. Master the "X-Treme" gauges in this flashy brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men-vs-street-fighter', 'Playstation', 'X-Men vs. Street Fighter', NULL, NULL, NULL, NULL, NULL, '2D tag-team fighting crossover.', 'Master the "Variable Assist" to defeat the ultimate threat.', 'A legendary arcade port featuring Marvel and Capcom stars.', 'X-Men vs. Street Fighter delivers massive combos and flashy specials. Switch between characters mid-fight in this high-energy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men:-children-of-the-atom', 'Playstation', 'X-Men: Children Of The Atom', NULL, NULL, NULL, NULL, NULL, '2D weapon-based fighting game featuring the X-Men.', 'Defeat Magneto and stop the mutant-human war.', 'The first Marvel fighter from the Capcom arcade era.', 'X-Men: Children Of The Atom features massive sprites and complex combos. Experience the foundation of the "Vs." series in this hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xena---warrior-princess', 'Playstation', 'Xena - Warrior Princess', NULL, NULL, NULL, NULL, NULL, '3D action-adventure based on the hit TV series.', 'Use the Chakram to defeat gods and monsters in ancient Greece.', 'A cinematic quest starring the Warrior Princess.', 'Xena - Warrior Princess features acrobatic combat and puzzles. Follow Xena''s journey to redeem her past in this 32-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xenogears-disc-1', 'Playstation', 'Xenogears (Disc 1)', NULL, NULL, NULL, NULL, NULL, 'Epic JRPG with turn-based and giant robot (Gear) combat.', 'Uncover the mystery of Fei''s past and the origins of humanity.', 'A profound and philosophical masterpiece from Square.', 'Xenogears (Disc 1) begins a massive tale of religion and identity. Master the "Combo" system both on foot and in your Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xenogears-disc-2', 'Playstation', 'Xenogears (Disc 2)', NULL, NULL, NULL, NULL, NULL, 'Epic JRPG with turn-based and giant robot (Gear) combat.', 'Face the final revelation and save the world from Deus.', 'The experimental and narrative-heavy conclusion to the epic.', 'Xenogears (Disc 2) features intense storytelling and massive boss fights. Experience one of the deepest plots in gaming history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xevious-3d-g+-usa', 'Playstation', 'Xevious 3D-G+ (USA)', NULL, NULL, NULL, NULL, NULL, '3D update to the classic vertical-scrolling shooter.', 'Blast through waves of alien ships in a 3D environment.', 'A high-tech compilation including the 3D-G edition.', 'Xevious 3D-G+ brings the arcade legend to the 32-bit era. Enjoy the original classics alongside this polished 3D remake.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xs-airboat-racing', 'Playstation', 'XS Airboat Racing', NULL, NULL, NULL, NULL, NULL, '3D boat racing across hazardous swamp and water tracks.', 'Win the airboat championship by outmaneuvering rivals.', 'A niche and fun water-based racing game.', 'XS Airboat Racing features unique physics and diverse tracks. Master the slides to cross the finish line first in this budget gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xs-junior-league-football', 'Playstation', 'XS Junior League Football', NULL, NULL, NULL, NULL, NULL, 'Arcade-style football featuring young athletes.', 'Lead your neighborhood team to a junior league title.', 'A simplified and fun take on American football for kids.', 'XS Junior League Football offers accessible controls and colorful graphics. Perfect for younger sports fans looking for a quick game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xs-junior-league-soccer', 'Playstation', 'XS Junior League Soccer', NULL, NULL, NULL, NULL, NULL, 'Arcade-style soccer featuring young athletes.', 'Outscore your rivals in this fast-paced junior league.', 'A lighthearted and family-friendly soccer simulation.', 'XS Junior League Soccer features simple mechanics and fun animations. Goal-scoring action designed for younger PlayStation players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('you-dont-know-jack---mock-2-usa', 'Playstation', 'You Don''t Know Jack - Mock 2 (USA)', NULL, NULL, NULL, NULL, NULL, 'Humorous trivia party game for multiple players.', 'Answer irreverent questions to win virtual cash and pride.', 'A witty and fast-paced quiz game with a cynical host.', 'You Don''t Know Jack - Mock 2 features hundreds of new questions. Test your knowledge and your funny bone in this multiplayer hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('you-dont-know-jack-usa-disc-1', 'Playstation', 'You Don''t Know Jack (USA) (Disc 1)', NULL, NULL, NULL, NULL, NULL, 'Humorous trivia party game with a focus on pop culture.', 'Prove your intelligence in "The Quiz Show Party Game."', 'The first disc of the legendary irreverent trivia series.', 'You Don''t Know Jack (Disc 1) delivers sharp humor and challenging puzzles. Perfect for game nights with friends who love a laugh.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('you-dont-know-jack-usa-disc-2', 'Playstation', 'You Don''t Know Jack (USA) (Disc 2)', NULL, NULL, NULL, NULL, NULL, 'Humorous trivia party game with a focus on pop culture.', 'Answer more bizarre questions in this content-rich sequel disc.', 'More episodes and more jokes from the iconic trivia series.', 'You Don''t Know Jack (Disc 2) expands the library of questions. Keep the party going with more snarky commentary and tricky facts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---forbidden-memories', 'Playstation', 'Yu-Gi-Oh! - Forbidden Memories', NULL, NULL, NULL, NULL, NULL, 'Strategic card-battling RPG set in Ancient Egypt.', 'Build the ultimate deck to defeat the High Mages and save Egypt.', 'A challenging and addictive card game based on the anime.', 'Yu-Gi-Oh! - Forbidden Memories features a unique fusion system. Collect rare cards and master the stars to become the Duel King.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---forbidden-memories---15-card-mod', 'Playstation', 'Yu-Gi-Oh! - Forbidden Memories - 15 Card Mod', NULL, NULL, NULL, NULL, NULL, 'Strategic card-battling RPG with a 15-card reward mod.', 'Earn 15 cards per win to build your ultimate deck faster.', 'A popular fan-mod that reduces the grind of the original game.', 'Forbidden Memories (15 Card Mod) allows players to collect powerful cards like Blue-Eyes White Dragon with much less effort.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---forbidden-memories---mod-dragon-ball-z-ver-53', 'Playstation', 'Yu-Gi-Oh! - Forbidden Memories - Mod dragon ball Z ver 5.3', NULL, NULL, NULL, NULL, NULL, 'Strategic card-battling crossover mod.', 'Duel using Dragon Ball Z characters and specialized cards.', 'A creative mod that replaces Yu-Gi-Oh characters with Saiyans.', 'Forbidden Memories (DBZ Mod) features Goku, Vegeta, and more. Experience a unique fusion of two legendary anime worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---forbidden-memories---mod-naruto-v2', 'Playstation', 'Yu-Gi-Oh! - Forbidden Memories - Mod Naruto V2', NULL, NULL, NULL, NULL, NULL, 'Strategic card-battling crossover mod.', 'Use Ninja techniques and Naruto characters to win duels.', 'A fan-made mod featuring the cast of the Hidden Leaf Village.', 'Forbidden Memories (Naruto V2) replaces traditional cards with Shinobi. Master the jutsus and defeat your rivals in this unique mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---forbidden-memories---mod-yuyu-hakusho', 'Playstation', 'Yu-Gi-Oh! - Forbidden Memories - Mod Yuyu Hakusho', NULL, NULL, NULL, NULL, NULL, 'Strategic card-battling crossover mod.', 'Duel using the supernatural cast of the YuYu Hakusho series.', 'A specialized mod for fans of the spirit detective saga.', 'Forbidden Memories (YuYu Hakusho) features Yusuke and his team. Experience a nostalgic trip with specialized card art and effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-monster-capsule:-breed-and-battle', 'Playstation', 'Yu-Gi-Oh! Monster Capsule: Breed and Battle', NULL, NULL, NULL, NULL, NULL, 'Tactical board-game and monster breeding sim.', 'Breed powerful monsters to win the ultimate capsule battle.', 'A rare and unique spin-off of the Yu-Gi-Oh! franchise.', 'Monster Capsule: Breed and Battle features tactical grid movement. Collect, train, and fight with your favorite monsters in this Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-divide', 'Playstation', 'Zero Divide', NULL, NULL, NULL, NULL, NULL, '3D fighting game featuring robotic "Cybra-style" warriors.', 'Win the mechanical tournament and master the "Armor" system.', 'A stylish and technical 3D brawler from Zoom.', 'Zero Divide features unique robot designs and fluid combat. Master the technical moves to dismantle your opponents in this cult hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-divide-2', 'Playstation', 'Zero Divide 2', NULL, NULL, NULL, NULL, NULL, '3D fighting game with improved graphics and new robots.', 'Dominate the arena in the ultimate mechanical showdown.', 'An refined and faster sequel to the original robot fighter.', 'Zero Divide 2: The Secret Worker offers more characters and better animations. Experience high-tech 3D brawling at its finest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop---americas-largest-killer-of-time!-usa', 'Playstation', 'Zoop - America''s Largest Killer of Time! (USA)', NULL, NULL, NULL, NULL, NULL, 'Fast-paced tile-matching puzzle game.', 'Match colored shapes to clear the screen before it fills up.', 'An addictive and colorful "killer of time" puzzler.', 'Zoop features a unique "capture and match" mechanic. Test your speed and strategy in this frantic and vibrant puzzle classic.');